-- ════════════════════════════════════════════════════════════════════════

insert into public.courses
  (id, title, description, ai_instructions, icon, color, category, subcategory, difficulty, locked, modules, translations)
values (
  'course-open-claw', 'OpenClaw: Tu Asistente de IA de Código Abierto', 'Un asistente de IA de código abierto que corre en tu propia computadora y te habla en WhatsApp, Telegram, Discord o Slack — sin depender de un servidor ajeno. Instálalo, entiende su arquitectura (Gateway, canales, plugins), y aprende a leer y contribuir a un proyecto de código abierto real y muy activo.', 'Eres el Mago, profesor de la Escuela de Programación de Oliver Academy, guiando el curso "OpenClaw". Explica la arquitectura del proyecto (Gateway, canales, plugins) con analogías claras, sé honesto sobre que es un proyecto que cambia rápido y las capturas de configuración exactas pueden variar entre versiones, y siempre recuerda las precauciones de seguridad (tratar mensajes entrantes como no confiables, no exponer el Gateway sin sandboxing) antes de sugerir una configuración avanzada.',
  '🦞', '#f97316', 'Programación', 'Código Abierto', 'intermedio', false,
  '[{"type":"text","title":"Bienvenida: un asistente de IA que es tuyo, de verdad","description":"Qué es OpenClaw, quién lo hace, y por qué es un buen proyecto para aprender de código abierto real.","content":"\n<h2>Qué es OpenClaw</h2>\n<p><strong>OpenClaw</strong> es un asistente de inteligencia artificial de código abierto que corre en <strong>tu propia computadora</strong> y te encuentra en los canales de mensajería que ya usas: WhatsApp, Telegram, Discord, Slack, Microsoft Teams, iMessage y más de 20 plataformas adicionales, además de apps nativas para macOS, iOS, Android, Windows y Linux. La misma instalación funciona como asistente personal en tu laptop o como despliegue compartido para un equipo — la diferencia es solo de configuración.</p>\n\n<h2>Tuyo, sin letra pequeña</h2>\n<p>A diferencia de un asistente de IA típico donde tus conversaciones viven en el servidor de una empresa, con OpenClaw tu <strong>estado, memoria y credenciales viven en tu propio hardware</strong>. Los modelos de IA que usa (Claude, Codex, modelos locales) son <em>plugins</em> intercambiables — puedes cambiar de proveedor sin cambiar nada más de tu configuración. Por defecto, OpenClaw no \"llama a casa\" salvo para una revisión diaria de versión; incluso eso se puede desactivar.</p>\n\n<h2>Quién lo mantiene</h2>\n<p>OpenClaw es desarrollado por la <strong>OpenClaw Foundation</strong>, una organización sin fines de lucro (501(c)(3)) independiente — no tiene plan de pago, servicio alojado, ni token. Nació del trabajo de Peter Steinberger y la comunidad, originalmente pensado para \"Molty\", un personaje de langosta espacial que es la mascota del proyecto (por eso el logo 🦞). Recibe apoyo de donantes como Amazon, Red Hat, GitHub, NVIDIA y otros — donantes que financian, no que son dueños del proyecto.</p>\n\n<h2>Por qué es un buen proyecto para este curso</h2>\n<p>Además de ser útil por sí mismo, OpenClaw es un ejemplo perfecto de proyecto de código abierto real, activo y bien documentado: código público, miles de contribuciones, una arquitectura clara que puedes leer, y una comunidad viva. Aprender a instalarlo, entender su arquitectura y (si quieres) contribuirle es una forma excelente de practicar lo que aprendiste en cualquier curso de Git y GitHub de esta escuela, sobre un proyecto real.</p>\n\n<div class=\"tip\">\n💡 Este curso trabaja junto con <em>Fundamentos del Código Abierto</em> de esta misma escuela: aquí ves un proyecto real de principio a fin; ahí ves las reglas generales (licencias, cómo contribuir) que aplican a cualquier proyecto, no solo a este.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Dónde viven tu estado, memoria y credenciales cuando usas OpenClaw?","options":["En un servidor de la empresa OpenClaw Foundation","En tu propio hardware — la computadora donde lo instalas","En la nube de OpenAI","No se guardan en ningún lado"],"correctIndex":1},"id":0,"order":0},{"type":"text","title":"Cómo se arma por dentro: el Gateway, los canales y los plugins","description":"La arquitectura de OpenClaw, en cuatro piezas que encajan entre sí.","content":"\n<h2>El Gateway: el centro de control</h2>\n<p>El <strong>Gateway</strong> es el plano de control local de OpenClaw: administra las sesiones de conversación, las herramientas que el asistente puede usar, los eventos, y las conexiones a los distintos canales de mensajería. Todo lo demás se conecta a él.</p>\n\n<h2>Cómo se conecta todo</h2>\n<table>\n<tr><th>Pieza</th><th>Qué hace</th></tr>\n<tr><td><strong>Gateway</strong></td><td>El plano de control local: sesiones, herramientas, eventos, conexiones.</td></tr>\n<tr><td><strong>Control UI, CLI y TUI</strong></td><td>Las distintas formas de hablar con el Gateway: una interfaz web, la línea de comandos, o una interfaz de texto en la terminal.</td></tr>\n<tr><td><strong>Canales</strong></td><td>Llevan al asistente a WhatsApp, Telegram, Slack, Discord, Google Chat, Signal, iMessage y más.</td></tr>\n<tr><td><strong>Apps y nodos compañeros</strong></td><td>Agregan voz, pizarra (Canvas), cámara, pantalla, y acciones locales del dispositivo en las plataformas que lo soportan.</td></tr>\n</table>\n\n<h2>Modelos y agentes como plugins intercambiables</h2>\n<p>OpenClaw funciona tanto con proveedores de modelos alojados (como Claude o modelos de OpenAI) como con modelos locales que corren en tu propia máquina, sin depender de internet. Sus <strong>herramientas, habilidades (skills) y plugins</strong> son lo que extiende lo que el asistente puede hacer — desde consultar el clima hasta ejecutar comandos en tu sistema, según cómo lo configures.</p>\n\n<h2>Un vistazo al repositorio</h2>\n<p>El proyecto vive como un <em>pnpm workspace</em> (un monorepo con varios paquetes relacionados) — si ya tomaste algún curso de Git y GitHub de esta escuela, el flujo para explorarlo te resultará familiar: clonar el repositorio, instalar dependencias, y correr el proyecto localmente.</p>\n<pre><code>git clone https://github.com/openclaw/openclaw.git\ncd openclaw\npnpm install\npnpm build</code></pre>\n\n<div class=\"tip\">\n💡 Fíjate en las carpetas del repositorio real: <code>apps</code> (las aplicaciones), <code>crates</code> (componentes en Rust), <code>config</code> (configuración) — leer la estructura de carpetas de un proyecto real, antes de leer una sola línea de código, ya te dice mucho sobre cómo está organizado.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué es el \"Gateway\" en la arquitectura de OpenClaw?","options":["Un canal de mensajería más","El plano de control local: administra sesiones, herramientas, eventos y las conexiones a los distintos canales","El nombre del modelo de IA que usa por defecto","Una app exclusiva para iPhone"],"correctIndex":1},"id":1,"order":1},{"type":"text","title":"Instala y arranca tu propio OpenClaw","description":"De cero a tu primer mensaje, con el instalador oficial.","content":"\n<h2>Requisitos y el instalador</h2>\n<p>El instalador de OpenClaw soporta macOS, Linux y Windows, y se encarga de instalar la versión de Node.js necesaria si no la tienes. Si ya administras tus propias versiones de Node.js, puedes instalar el paquete directamente en vez de usar el script del instalador.</p>\n\n<table>\n<tr><th>Sistema</th><th>Comando</th></tr>\n<tr><td>macOS / Linux / WSL2</td><td><code>curl -fsSL https://openclaw.ai/install.sh | bash</code></td></tr>\n<tr><td>Windows (PowerShell)</td><td><code>iwr -useb https://openclaw.ai/install.ps1 | iex</code></td></tr>\n<tr><td>Si ya tienes Node.js</td><td><code>npm install -g openclaw@latest</code></td></tr>\n</table>\n\n<div class=\"warn\">\n⚠️ Como con cualquier script de instalación que descargas y ejecutas (visto en el curso de <em>Termux</em> de la Academia de Linux), es buena práctica revisar qué hace un instalador antes de correrlo con privilegios, especialmente la primera vez que usas un proyecto nuevo.\n</div>\n\n<h2>El asistente de configuración (onboarding)</h2>\n<p>Al instalar por primera vez, un asistente interactivo te guía paso a paso: verifica el acceso a los modelos de IA que quieras usar, crea tu espacio de trabajo, y configura el Gateway. Si instalaste el paquete directamente, puedes iniciar este proceso a mano:</p>\n<pre><code>openclaw onboard --install-daemon</code></pre>\n\n<h2>Tus primeros comandos</h2>\n<table>\n<tr><th>Comando</th><th>Qué hace</th></tr>\n<tr><td><code>openclaw gateway status</code></td><td>Revisa que el Gateway esté corriendo correctamente.</td></tr>\n<tr><td><code>openclaw dashboard</code></td><td>Abre la interfaz de control (Control UI) en tu navegador.</td></tr>\n</table>\n<p>Desde el dashboard, envía un mensaje de prueba para confirmar que el asistente responde — esa es la señal de que tu instalación quedó lista.</p>\n\n<h2>Conectar un canal de mensajería</h2>\n<p>Después del arranque inicial, conectas los canales que quieras usar (WhatsApp, Telegram, Discord...) siguiendo la guía de configuración de cada uno — cada canal tiene su propio proceso de vinculación, similar a cómo vinculas WhatsApp Web con tu teléfono.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué hace el comando \"openclaw dashboard\"?","options":["Desinstala OpenClaw","Abre la interfaz de control (Control UI) en tu navegador","Conecta automáticamente todos los canales de mensajería sin configuración","Actualiza el sistema operativo"],"correctIndex":1},"id":2,"order":2},{"type":"text","title":"Seguridad: trata los mensajes entrantes como no confiables","description":"El asistente puede actuar de verdad en tu sistema — por eso la seguridad no es opcional.","content":"\n<h2>Una diferencia importante con un chatbot normal</h2>\n<p>OpenClaw no solo responde texto: según cómo lo configures, puede ejecutar herramientas reales en tu sistema. Eso lo hace mucho más útil que un chatbot que solo conversa — y también significa que hay que tratarlo con el mismo cuidado que cualquier programa con permisos sobre tu computadora.</p>\n\n<h2>La regla central: mensajes entrantes no confiables por defecto</h2>\n<div class=\"warn\">\n⚠️ OpenClaw trata los mensajes entrantes como <strong>entrada no confiable</strong> por defecto. Los canales que permiten mensajes directos emparejan a remitentes desconocidos antes de que puedan interactuar contigo — tienes que aprobar explícitamente una solicitud de emparejamiento (<code>openclaw pairing approve &lt;canal&gt; &lt;código&gt;</code>) antes de que un desconocido pueda hablarle a tu asistente.\n</div>\n\n<h2>Dónde corren las herramientas</h2>\n<p>Por defecto, las herramientas que usa OpenClaw corren directamente en tu computadora (el host) para la sesión principal, salvo que configures explícitamente un entorno aislado (<em>sandboxing</em>). Antes de conectar a otras personas a tu instancia, o de exponer el Gateway de forma remota, el proyecto recomienda leer su guía de seguridad y su guía de sandboxing con atención.</p>\n\n<h2>Buenas prácticas al configurar tu instancia</h2>\n<table>\n<tr><th>Práctica</th><th>Por qué</th></tr>\n<tr><td>No expongas el Gateway a internet sin entender las implicaciones</td><td>Un Gateway expuesto sin protección adecuada podría permitir que alguien más controle tu asistente (y, por extensión, herramientas con acceso a tu sistema).</td></tr>\n<tr><td>Revisa qué herramientas/plugins habilitas</td><td>Cada herramienta que agregas amplía lo que el asistente puede hacer en tu nombre.</td></tr>\n<tr><td>Empieza en modo local de confianza antes de compartir tu instancia</td><td>Familiarízate con el comportamiento antes de abrirlo a un equipo o a canales públicos.</td></tr>\n<tr><td>Aprueba emparejamientos solo de gente que conoces</td><td>Es la primera línea de defensa contra mensajes entrantes maliciosos.</td></tr>\n</table>\n\n<div class=\"tip\">\n💡 Este mismo principio (tratar la entrada externa como no confiable, pedir confirmación antes de acciones con efectos reales) es el mismo que viste en <em>Actualidad de la IA</em> sobre agentes de IA en general — OpenClaw es un ejemplo concreto y real de ese principio aplicado.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué OpenClaw trata los mensajes entrantes como \"no confiables\" por defecto?","options":["Porque no funciona bien con ningún canal","Porque el asistente puede ejecutar herramientas reales en tu sistema, así que un mensaje malicioso de un desconocido podría intentar aprovecharse de eso","Porque es un requisito legal sin relación con la seguridad","Porque todos los mensajes se eliminan automáticamente"],"correctIndex":1},"id":3,"order":3},{"type":"text","title":"Personaliza tu asistente: habilidades y plugins","description":"Cómo extender lo que OpenClaw puede hacer, sin modificar el núcleo del proyecto.","content":"\n<h2>Habilidades (skills) y plugins</h2>\n<p>OpenClaw se extiende agregando <strong>herramientas, habilidades (skills) y plugins</strong> — piezas que le dan al asistente nuevas capacidades sin tocar el código del núcleo del proyecto. Es el mismo principio de diseño que viste en <em>Termux</em> con sus paquetes instalables: un núcleo estable, extendido por piezas intercambiables.</p>\n\n<h2>Dónde encontrar habilidades ya hechas</h2>\n<p>Existe una comunidad activa construyendo y compartiendo configuraciones y plantillas de habilidades para OpenClaw (por ejemplo, colecciones curadas con cientos de plantillas listas, organizadas por categoría) — un patrón muy parecido al de cualquier ecosistema de plugins maduro, donde no siempre hace falta construir algo desde cero.</p>\n\n<h2>Compañeros de plataforma: voz, pantalla y dispositivo</h2>\n<p>Según la plataforma, apps y nodos compañeros agregan capacidades adicionales: interacción por voz, una pizarra compartida (Canvas), acceso a cámara, captura de pantalla, y acciones específicas del dispositivo — todo como piezas opcionales, no como parte obligatoria del núcleo.</p>\n\n<h2>El principio de diseño detrás de todo esto</h2>\n<table>\n<tr><th>Principio</th><th>Qué significa en la práctica</th></tr>\n<tr><td>Núcleo estable</td><td>El Gateway y su arquitectura central cambian con cuidado, con un proceso formal de contribución.</td></tr>\n<tr><td>Extensión mediante plugins</td><td>Nuevas capacidades se agregan sin modificar el núcleo, reduciendo el riesgo de romper algo al extenderlo.</td></tr>\n<tr><td>Modelos como plugins también</td><td>Cambiar de proveedor de IA (Claude, Codex, un modelo local) no requiere reescribir tu configuración de canales o herramientas.</td></tr>\n</table>\n\n<div class=\"tip\">\n💡 Diseñar sistemas con un núcleo pequeño y estable, extendido por piezas intercambiables, es un patrón que vas a ver una y otra vez en software bien construido — vale la pena reconocerlo cuando lo veas en otros proyectos.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es la ventaja de diseñar OpenClaw con un \"núcleo estable\" extendido por plugins?","options":["Ninguna, sería mejor tenerlo todo en un solo archivo","Nuevas capacidades se pueden agregar sin modificar el núcleo, reduciendo el riesgo de romper el sistema central al extenderlo","Hace que el proyecto sea más difícil de instalar","Impide que el proyecto use más de un modelo de IA"],"correctIndex":1},"id":4,"order":4},{"type":"text","title":"Cómo contribuir: tu primer Pull Request a un proyecto real","description":"De leer el código a proponer tu primer cambio, paso a paso.","content":"\n<h2>Antes de escribir una sola línea</h2>\n<ol>\n<li><strong>Lee el archivo CONTRIBUTING.md</strong> del proyecto — casi todo proyecto serio de código abierto tiene uno, con las reglas específicas de ese repositorio.</li>\n<li><strong>Revisa los issues abiertos</strong> — muchos proyectos etiquetan tareas pequeñas como \"good first issue\" para quien empieza.</li>\n<li><strong>Únete a la comunidad</strong> (en el caso de OpenClaw, su servidor de Discord) para hacer preguntas de configuración antes de intentar resolver algo por tu cuenta.</li>\n</ol>\n\n<h2>El flujo típico de contribución (repaso de Git y GitHub)</h2>\n<p>Si tomaste el curso <em>Git y GitHub: de Cero a Experto</em> de esta escuela, este flujo te va a resultar familiar:</p>\n<ol>\n<li><strong>Fork</strong> del repositorio a tu propia cuenta.</li>\n<li><strong>Clona</strong> tu fork localmente.</li>\n<li>Crea una <strong>rama</strong> nueva para tu cambio.</li>\n<li>Haz el cambio, con <strong>commits</strong> claros.</li>\n<li><strong>Push</strong> a tu fork, y abre un <strong>Pull Request</strong> hacia el repositorio original.</li>\n<li>Responde a los comentarios de revisión — es normal que te pidan ajustes antes de aceptar el cambio.</li>\n</ol>\n\n<h2>Contribuir no es solo código</h2>\n<p>Como viste en <em>Historia de Linux</em>, un proyecto de código abierto necesita mucho más que código: documentación, reportes de errores claros, traducciones, y ayuda respondiendo preguntas de otros usuarios — todo eso cuenta como contribución real.</p>\n\n<table>\n<tr><th>Si sabes...</th><th>Puedes contribuir con...</th></tr>\n<tr><td>Usar OpenClaw</td><td>Reportar errores con pasos claros para reproducirlos.</td></tr>\n<tr><td>Escribir bien</td><td>Mejorar la documentación o las guías de configuración.</td></tr>\n<tr><td>Programar</td><td>Resolver issues etiquetados como buenos para empezar.</td></tr>\n<tr><td>Diseñar habilidades/plugins</td><td>Construir y compartir una habilidad nueva con la comunidad.</td></tr>\n</table>\n\n<div class=\"warn\">\n⚠️ Los proyectos de este tamaño (miles de contribuciones activas) reciben ayuda asistida por IA con gusto, pero cada Pull Request sigue necesitando que <strong>tú</strong> entiendas y puedas explicar el cambio que propones — no basta con generar un cambio y enviarlo sin revisarlo.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es el primer paso recomendado antes de intentar contribuir código a un proyecto como OpenClaw?","options":["Escribir código inmediatamente sin revisar nada más","Leer el archivo CONTRIBUTING.md del proyecto y revisar los issues etiquetados para quien empieza","Reescribir el proyecto completo desde cero","Contactar directamente a cada donante del proyecto"],"correctIndex":1},"id":5,"order":5},{"type":"text","title":"Un ecosistema más grande: OpenClaw dentro de un equipo de agentes","description":"Cómo OpenClaw se conecta con otras herramientas, incluida Paperclip.","content":"\n<h2>OpenClaw no vive solo</h2>\n<p>OpenClaw funciona junto a otras herramientas de IA del mismo ecosistema: junto a Claude Code y Codex (que viste en <em>Domina Claude</em> y en el <em>Panorama de Modelos de IA</em>) como opciones de \"harness\" (el agente que ejecuta las tareas), y como una de las piezas que otras herramientas de orquestación pueden coordinar.</p>\n\n<h2>La analogía \"empleado vs. compañía\"</h2>\n<p>Una forma útil de pensar en esto, que verás con más detalle en el curso <em>Paperclip</em> de esta misma escuela: si OpenClaw es un empleado individual — un asistente que hace su trabajo — hay herramientas de orquestación que actúan como \"la compañía\": coordinan a varios agentes (OpenClaw, Claude Code, Codex y otros) trabajando juntos hacia un objetivo, con roles, presupuestos y supervisión.</p>\n\n<h2>Por qué esto importa para entender el panorama actual</h2>\n<p>Como viste en <em>Actualidad de la IA</em>, la tendencia de fondo es pasar de \"un chatbot que responde\" a \"agentes que actúan\" — y ahora, un paso más allá: <strong>equipos completos de agentes</strong> coordinados entre sí. OpenClaw representa el nivel de \"un asistente capaz\"; el siguiente curso de esta escuela te lleva al nivel de \"coordinar varios de ellos\".</p>\n\n<div class=\"tip\">\n💡 Si ya instalaste OpenClaw en la clase de instalación de este curso, ya tienes la pieza base lista para explorar, más adelante, cómo se vería coordinarlo junto a otros agentes.\n</div>\n\n<h2>Cierre del curso</h2>\n<p>En este curso viste qué es OpenClaw, su arquitectura (Gateway, canales, plugins), cómo instalarlo y usarlo con seguridad, cómo extenderlo, y cómo contribuir a un proyecto de código abierto real y activo. Sigue con <em>Paperclip</em> para ver el siguiente nivel: coordinar equipos completos de agentes de IA.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cómo se describe la relación entre OpenClaw y una herramienta de orquestación como Paperclip?","options":["No tienen ninguna relación entre sí","OpenClaw es como un empleado individual (un asistente capaz); una herramienta de orquestación actúa como \"la compañía\", coordinando varios agentes juntos","Paperclip reemplaza por completo a OpenClaw","Son exactamente el mismo software con distinto nombre"],"correctIndex":1},"id":6,"order":6}]',
  '{}'::jsonb
)
on conflict (id) do update set
  title = excluded.title, description = excluded.description, ai_instructions = excluded.ai_instructions,
  icon = excluded.icon, color = excluded.color, category = excluded.category,
  subcategory = excluded.subcategory, difficulty = excluded.difficulty, locked = excluded.locked,
  modules = excluded.modules, translations = excluded.translations, updated_at = now();

insert into public.courses
  (id, title, description, ai_instructions, icon, color, category, subcategory, difficulty, locked, modules, translations)
values (
  'course-paperclip', 'Paperclip: Organiza un Equipo de Agentes de IA', 'Un proyecto de código abierto más nuevo que OpenClaw, pero en el mismo espacio: en vez de un solo asistente, Paperclip organiza equipos completos de agentes de IA (OpenClaw, Claude Code, Codex, Cursor) como si fueran una empresa — con organigrama, presupuestos y aprobaciones. La siguiente capa de la automatización con IA.', 'Eres el Mago, profesor de la Escuela de Programación de Oliver Academy, guiando el curso "Paperclip". Explica los conceptos de organización de agentes (organigrama, presupuestos, gobernanza) con analogías del mundo laboral real, y sé honesto sobre que Paperclip es un proyecto joven y en evolución rápida — algunas funciones exactas del roadmap pueden cambiar. Recuerda siempre el principio de "nada se ejecuta sin tu aprobación" antes de sugerir dar autonomía amplia a un agente.',
  '📎', '#0ea5e9', 'Programación', 'Código Abierto', 'intermedio', false,
  '[{"type":"text","title":"Bienvenida: si OpenClaw es un empleado, Paperclip es la empresa","description":"Un proyecto más nuevo, en el mismo terreno que OpenClaw, resolviendo un problema distinto.","content":"\n<h2>Qué es Paperclip</h2>\n<p><strong>Paperclip</strong> es una aplicación de código abierto (licencia MIT) para <strong>orquestar equipos de agentes de IA</strong> que trabajan para ti. Es un servidor Node.js con una interfaz web en React que coordina a varios agentes de IA hacia objetivos de negocio, con seguimiento de trabajo y costos desde un solo panel — no es un chatbot, es lo que administra a muchos \"agentes-empleado\" a la vez.</p>\n\n<h2>\"Si OpenClaw es un empleado, Paperclip es la compañía\"</h2>\n<p>Esta es literalmente la frase con la que el propio proyecto se describe. Mientras que OpenClaw (curso anterior de esta escuela) es un asistente individual capaz de actuar, Paperclip resuelve un problema distinto: <strong>¿qué pasa cuando tienes varios agentes trabajando a la vez</strong> — algunos de OpenClaw, otros Claude Code, otros Codex, otros Cursor — <strong>y necesitas coordinarlos, no perder el hilo de qué hace cada uno, y controlar el gasto?</strong></p>\n\n<h2>Un proyecto joven, con enfoque claro</h2>\n<p>Paperclip es, en efecto, más reciente que OpenClaw, y explícitamente se apoya en herramientas como OpenClaw, Claude Code y Codex — las orquesta, no las reemplaza. Es desarrollado por Paperclip Labs, Inc., publicado bajo licencia MIT (código abierto, uso libre incluido comercial).</p>\n\n<h2>El problema real que resuelve</h2>\n<div class=\"example\">\nImagina que tienes 20 pestañas de un agente de código abierto abiertas a la vez, cada una trabajando en algo distinto. Pierdes de vista cuál hace qué, cuánto gasta cada una en tokens, y si alguna se quedó en un ciclo improductivo gastando dinero sin avanzar. Paperclip existe exactamente para ese problema: un panel único, con organigrama, presupuestos y supervisión, en vez de una pila desorganizada de scripts y pestañas de terminal.\n</div>\n\n<h2>Lo que este curso NO es</h2>\n<p>Como el propio proyecto aclara: Paperclip no es un chatbot, no es un framework para construir agentes desde cero, y no es un gestor de flujos de arrastrar-y-soltar. Es específicamente una herramienta de <strong>organización y gobernanza</strong> de agentes que ya existen y ya saben hacer su trabajo.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es la relación entre OpenClaw y Paperclip, según la propia descripción del proyecto?","options":["Son exactamente el mismo software","Si OpenClaw es un empleado individual, Paperclip es la compañía que organiza y coordina a varios agentes (incluido OpenClaw) a la vez","Paperclip es más antiguo que OpenClaw","No tienen ninguna relación"],"correctIndex":1},"id":0,"order":0},{"type":"text","title":"Los cuatro pilares de Paperclip","description":"Tareas, organigrama, entrenamiento e infraestructura — las cuatro piezas que hacen que un equipo de agentes funcione.","content":"\n<h2>Por qué cuatro pilares</h2>\n<p>Según el propio proyecto, cuatro cosas tienen que funcionar bien para que una organización de agentes de IA produzca resultados de verdad. Paperclip está construido exactamente alrededor de esas cuatro piezas.</p>\n\n<table>\n<tr><th>Pilar</th><th>Para quién</th><th>Qué cubre</th></tr>\n<tr><td><strong>Gestor de tareas agentic</strong></td><td>Todos, uso diario</td><td>Declaras la intención, los agentes trabajan, tú verificas el resultado. Incluye aprobaciones y revisión de cambios.</td></tr>\n<tr><td><strong>Organigrama para agentes</strong></td><td>Gerentes</td><td>Roles, permisos y límites — tanto para humanos como para agentes en el mismo organigrama.</td></tr>\n<tr><td><strong>Entrenamiento de agentes-empleado</strong></td><td>Quien habilita el sistema</td><td>Diseñar, entrenar y evaluar a tus \"empleados\" de IA con habilidades compartidas.</td></tr>\n<tr><td><strong>Sistema operativo agentic</strong></td><td>IT / plataforma</td><td>La infraestructura que hace que todo corra: cualquier modelo, cualquier agente, aislamiento de ejecución, controles de costo.</td></tr>\n</table>\n\n<h2>\"Declara la intención, verifica el resultado\"</h2>\n<p>El primer pilar resume bien la filosofía completa del proyecto: tú no microgestionas cada paso — defines <strong>qué</strong> necesitas, el agente trabaja de forma más autónoma, y tú revisas el resultado final (a partir de diferencias de código, capturas de pantalla, o pruebas) antes de aceptarlo.</p>\n\n<h2>Un organigrama mixto: humanos y agentes juntos</h2>\n<p>Una idea distintiva de Paperclip: el organigrama no es solo de agentes — mezcla personas y agentes de IA en la misma estructura, con roles, responsabilidades, y reglas claras de quién puede delegar en quién, y quién puede hacer qué.</p>\n\n<div class=\"tip\">\n💡 Piensa en los cuatro pilares como las cuatro preguntas que cualquier equipo real (humano o de IA) necesita responder: ¿qué hay que hacer?, ¿quién es responsable de qué?, ¿cómo mejoramos con el tiempo?, y ¿con qué infraestructura corre todo esto?\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué idea resume mejor el primer pilar, \"Gestor de tareas agentic\"?","options":["Microgestionar cada paso que da el agente en tiempo real","Declarar la intención (qué necesitas), dejar que el agente trabaje con más autonomía, y verificar el resultado final antes de aceptarlo","Nunca revisar el trabajo de los agentes","Solo funciona con un agente a la vez"],"correctIndex":1},"id":1,"order":1},{"type":"text","title":"Organigrama, tareas y \"heartbeats\": cómo trabajan los agentes","description":"La mecánica concreta detrás de cómo Paperclip mantiene a los agentes trabajando de forma ordenada.","content":"\n<h2>Organigrama con roles reales</h2>\n<p>Cada agente en Paperclip tiene un <strong>rol, un título, y una línea de reporte</strong> — de forma parecida a un organigrama de empresa real. Un agente puede ser \"CTO\", otro \"ingeniero\", otro \"diseñador\" — cada uno con permisos y responsabilidades acotadas a su rol.</p>\n\n<h2>El sistema de tickets: nada se pierde</h2>\n<p>El trabajo se organiza en <strong>tickets</strong> (issues) con vínculos a la empresa/proyecto/objetivo correspondiente, checkout atómico (para que dos agentes no trabajen accidentalmente sobre lo mismo a la vez), dependencias, comentarios, documentos adjuntos, y productos de trabajo — cada conversación queda registrada, cada decisión queda trazada.</p>\n\n<h2>Heartbeats: cómo \"despiertan\" los agentes</h2>\n<p>En vez de correr todo el tiempo consumiendo recursos sin parar, los agentes de Paperclip funcionan por <strong>heartbeats</strong> (latidos): se activan en un horario programado o quiando ocurre un evento (se les asigna una tarea, alguien los menciona), revisan su trabajo pendiente, y actúan. La delegación fluye hacia arriba y abajo del organigrama según haga falta.</p>\n\n<table>\n<tr><th>Concepto</th><th>Qué resuelve</th></tr>\n<tr><td>Checkout atómico</td><td>Evita que dos agentes trabajen sobre la misma tarea sin saberlo (doble trabajo).</td></tr>\n<tr><td>Estado persistente</td><td>Un agente retoma exactamente donde se quedó en su próximo heartbeat, en vez de empezar de cero.</td></tr>\n<tr><td>Rutinas programadas</td><td>Tareas recurrentes (soporte al cliente, reportes) se activan solas según un horario, sin que tengas que iniciarlas a mano cada vez.</td></tr>\n</table>\n\n<h2>Espacios de trabajo aislados</h2>\n<p>Cada agente trabaja en su propio espacio de ejecución aislado (por ejemplo, un <em>git worktree</em> separado — si tomaste algún curso de Git de esta escuela, ya conoces el concepto), con el directorio y contexto correctos cada vez, evitando que el trabajo de un agente interfiera con el de otro.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué son los \"heartbeats\" en Paperclip?","options":["Un indicador de la salud física del servidor","El mecanismo por el que los agentes se activan según un horario o un evento, revisan su trabajo pendiente y actúan, en vez de correr sin parar","Un tipo de error del sistema","El nombre del organigrama de la empresa"],"correctIndex":1},"id":2,"order":2},{"type":"text","title":"Presupuestos y gobernanza: nada se sale de control","description":"Cómo Paperclip evita que un agente autónomo gaste de más o actúe sin supervisión.","content":"\n<h2>El problema del gasto descontrolado</h2>\n<p>Un agente de IA autónomo, corriendo sin supervisión, puede quedarse en un ciclo repitiendo llamadas al modelo sin avanzar realmente — y cada una de esas llamadas cuesta dinero real. Sin control, esto puede consumir cientos de dólares en tokens antes de que alguien se dé cuenta.</p>\n\n<h2>Control de costos por capas</h2>\n<table>\n<tr><th>Nivel de seguimiento</th><th>Qué controla</th></tr>\n<tr><td>Por compañía</td><td>Presupuesto total de toda la organización de agentes.</td></tr>\n<tr><td>Por agente</td><td>Presupuesto mensual individual — cuando un agente llega a su límite, se detiene.</td></tr>\n<tr><td>Por proyecto/objetivo/ticket</td><td>Seguimiento granular de en qué se está gastando exactamente.</td></tr>\n</table>\n<p>Cuando un presupuesto se agota, el sistema puede pausar automáticamente al agente responsable y cancelar el trabajo en cola, evitando el gasto descontrolado.</p>\n\n<h2>Gobernanza: aprobar, pausar, revertir</h2>\n<p>Las <strong>puertas de aprobación</strong> (approval gates) son puntos donde un humano debe revisar y aprobar antes de que el trabajo continúe — puedes aprobar contrataciones de agentes, anular una estrategia, pausar o terminar cualquier agente en cualquier momento. Los cambios de configuración quedan versionados, así que un cambio problemático se puede revertir de forma segura.</p>\n\n<h2>Auditoría completa</h2>\n<p>Cada acción que modifica algo, cada cambio de estado de un heartbeat, cada evento de costo, cada aprobación, queda registrado como actividad duradera — para que quien opera el sistema pueda auditar qué pasó y por qué, en cualquier momento.</p>\n\n<div class=\"warn\">\n⚠️ Este es exactamente el principio de \"confirma antes de una acción difícil de revertir\" que viste en <em>Actualidad de la IA</em> y en <em>Domina Claude</em>, aplicado a escala de todo un equipo de agentes en vez de a uno solo. Cuanta más autonomía le das a un sistema de este tipo, más importante es tener presupuestos y puertas de aprobación bien configuradas.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué pasa cuando un agente en Paperclip llega a su límite de presupuesto?","options":["Nada, sigue gastando sin límite","El sistema puede pausarlo automáticamente y cancelar el trabajo en cola, evitando gasto descontrolado","Se elimina permanentemente de la organización","El presupuesto de toda la compañía se duplica automáticamente"],"correctIndex":1},"id":3,"order":3},{"type":"text","title":"Instala y prueba Paperclip","description":"De cero a tu primera \"empresa\" de agentes, con el modo de prueba sin instalación permanente.","content":"\n<h2>Requisitos</h2>\n<p>Paperclip requiere Node.js 24.11 o más reciente y pnpm 9.15 o más reciente. Es de código abierto y autoalojado (self-hosted) — no requiere una cuenta de Paperclip para usarlo.</p>\n\n<h2>Instalación estándar</h2>\n<pre><code>curl -fsSLO https://paperclip.ing/install.sh\ncurl -fsSLO https://paperclip.ing/install.sh.sha256\nsha256sum -c install.sh.sha256\nbash install.sh</code></pre>\n<p>El instalador verifica que tengas Node.js, instala una CLI administrada, y arranca la configuración inicial interactiva. También puede instalar Paperclip como servicio en segundo plano en sistemas Linux y macOS soportados.</p>\n\n<div class=\"tip\">\n💡 Fíjate en el paso de verificación con <code>sha256sum</code>: es exactamente la misma técnica que viste en el curso de <em>Instala Linux</em> de la Academia de Linux para confirmar que un archivo descargado no está dañado ni alterado — aparece aquí por la misma razón.\n</div>\n\n<h2>Probarlo sin instalar nada permanente</h2>\n<p>Si solo quieres probarlo, existe un modo de \"prueba de manejo\" (test-drive) que se queda en primer plano, nunca instala un servicio, y ya viene inicializado con un agente \"CEO\" listo para empezar:</p>\n<pre><code>ANTHROPIC_API_KEY=... npx paperclipai test-drive</code></pre>\n<p>También puedes usar otros proveedores, especificando el \"harness\" (el tipo de agente) que quieres probar:</p>\n<pre><code>OPENAI_API_KEY=... npx paperclipai test-drive --harness codex</code></pre>\n\n<h2>Instalación manual (para desarrolladores)</h2>\n<pre><code>git clone https://github.com/paperclipai/paperclip.git\ncd paperclip\npnpm install\npnpm dev</code></pre>\n<p>Esto arranca el servidor de API en <code>http://localhost:3100</code>, con una base de datos PostgreSQL incrustada que se crea automáticamente — sin configuración manual de base de datos necesaria para probarlo localmente.</p>\n\n<div class=\"warn\">\n⚠️ Cualquier llave de API que uses (Anthropic, OpenAI) es una credencial real — trátala con el mismo cuidado que viste en <em>Domina Claude</em> sobre no compartir tus llaves ni subirlas a un repositorio público.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Para qué sirve el modo \"test-drive\" de Paperclip?","options":["Para desinstalar Paperclip permanentemente","Para probarlo sin instalar nada permanente — se queda en primer plano y ya viene inicializado con un agente listo","Es obligatorio usarlo antes de cualquier instalación","Solo funciona sin conexión a internet"],"correctIndex":1},"id":4,"order":4},{"type":"text","title":"Casos de uso reales: qué se puede coordinar con Paperclip","description":"De \"20 pestañas de Claude Code abiertas\" a un proceso ordenado con roles y presupuesto.","content":"\n<h2>El \"antes y después\" que resuelve Paperclip</h2>\n<table>\n<tr><th>Sin Paperclip</th><th>Con Paperclip</th></tr>\n<tr><td>20 pestañas de un agente de código abierto, sin saber cuál hace qué; al reiniciar, se pierde todo.</td><td>Tareas basadas en tickets, conversaciones organizadas por hilos, las sesiones persisten entre reinicios.</td></tr>\n<tr><td>Reunir manualmente contexto de varios lugares cada vez que le hablas a tu agente.</td><td>El contexto fluye desde la tarea hacia arriba, pasando por el proyecto y los objetivos de la empresa — el agente siempre sabe el \"por qué\".</td></tr>\n<tr><td>Carpetas de configuraciones de agentes desorganizadas, reinventando gestión de tareas cada vez.</td><td>Organigrama, tickets, delegación y gobernanza ya integrados de fábrica.</td></tr>\n<tr><td>Ciclos que gastan cientos de dólares antes de notarlo.</td><td>Seguimiento de costos y presupuestos que detienen a los agentes automáticamente al llegar al límite.</td></tr>\n<tr><td>Trabajos recurrentes que hay que recordar iniciar manualmente.</td><td>Rutinas (heartbeats) que se activan solas según un horario.</td></tr>\n</table>\n\n<h2>Un ejemplo de flujo completo</h2>\n<div class=\"example\">\nDefines el objetivo: \"Construir la app de notas número 1 de IA hasta $1M de ingresos mensuales.\" Contratas al equipo: un CEO, un CTO, ingenieros, diseñadores, marketing — cada rol puede ser cualquier agente, de cualquier proveedor. Apruebas la estrategia, defines presupuestos, y monitoreas desde el panel — en vez de coordinar manualmente cada pieza tú mismo.\n</div>\n\n<h2>Con quién funciona</h2>\n<p>Paperclip está diseñado para trabajar con OpenClaw, Claude Code, Codex, Cursor, y prácticamente cualquier cosa que pueda \"recibir un heartbeat\" — incluidos scripts de Bash o servicios por HTTP. No te obliga a un solo proveedor de IA.</p>\n\n<h2>Para quién es (y para quién no)</h2>\n<table>\n<tr><th>Te conviene si...</th><th>Probablemente no lo necesitas si...</th></tr>\n<tr><td>Coordinas varios agentes distintos hacia un objetivo común.</td><td>Usas un solo agente ocasionalmente para tareas simples.</td></tr>\n<tr><td>Necesitas auditar el trabajo y controlar costos de un equipo de agentes.</td><td>No te importa el seguimiento formal de tareas ni presupuestos.</td></tr>\n<tr><td>Quieres supervisar agentes autónomos corriendo 24/7 desde tu teléfono.</td><td>Prefieres supervisar directamente cada sesión de forma manual.</td></tr>\n</table>\n","exercises":[],"resources":[],"quiz":{"question":"¿Con qué tipo de agentes o herramientas puede trabajar Paperclip, según esta clase?","options":["Solo con un proveedor exclusivo de IA","Con OpenClaw, Claude Code, Codex, Cursor, y prácticamente cualquier cosa que pueda \"recibir un heartbeat\", incluidos scripts propios","Únicamente con modelos de código cerrado","Solo puede coordinar un agente a la vez"],"correctIndex":1},"id":5,"order":5},{"type":"text","title":"Cierre: el panorama completo de la automatización con IA","description":"De un prompt suelto a un equipo completo — repaso de todo el camino que recorriste.","content":"\n<h2>El camino completo, en una tabla</h2>\n<table>\n<tr><th>Nivel</th><th>Qué hace</th><th>Dónde lo viste</th></tr>\n<tr><td>Un prompt</td><td>Le pides algo a un chatbot y lees la respuesta.</td><td><em>Trucos y Consejos</em></td></tr>\n<tr><td>Un asistente con herramientas</td><td>El modelo busca en internet, ejecuta código, usa integraciones.</td><td><em>Domina Claude</em>, <em>Domina Gemini</em></td></tr>\n<tr><td>Un agente de código</td><td>Trabaja sobre un proyecto completo, con supervisión puntual.</td><td><em>Domina Claude</em> (Claude Code)</td></tr>\n<tr><td>Un asistente personal siempre activo</td><td>Corre en tu propio dispositivo, te encuentra en tus canales de siempre.</td><td><em>OpenClaw</em></td></tr>\n<tr><td>Un equipo completo de agentes</td><td>Varios agentes coordinados con organigrama, presupuesto y gobernanza.</td><td><em>Paperclip</em> (este curso)</td></tr>\n</table>\n\n<h2>Un recordatorio importante para cerrar</h2>\n<div class=\"warn\">\n⚠️ Cuanto más alto subes en esta escalera de autonomía, más importante se vuelve todo lo que viste en <em>Ética e Impacto de la IA</em> y en <em>Actualidad de la IA</em>: supervisión humana real, presupuestos claros, y la costumbre de revisar antes de confiar ciegamente. Un equipo de agentes mal supervisado no es solo un chatbot equivocado — puede significar código en producción, gasto real, o decisiones de negocio tomadas sin ti.\n</div>\n\n<h2>Lo que aprendiste en este curso</h2>\n<ul>\n<li>Qué es Paperclip y en qué se diferencia de un asistente individual como OpenClaw.</li>\n<li>Sus cuatro pilares: tareas, organigrama, entrenamiento e infraestructura.</li>\n<li>Cómo funcionan los heartbeats, los tickets y los espacios de trabajo aislados.</li>\n<li>Cómo controla presupuestos y aplica gobernanza sobre agentes autónomos.</li>\n<li>Cómo instalarlo y probarlo, incluido el modo sin instalación permanente.</li>\n</ul>\n\n<h2>Siguiente paso</h2>\n<p>Si te interesa este espacio, revisa también <em>Fundamentos del Código Abierto</em> (las reglas generales de licencias y contribución que aplican a cualquier proyecto como estos dos) y <em>Historia de los Agentes de IA Autónomos</em> (de dónde viene esta ola de herramientas y hacia dónde parece ir).</p>\n","exercises":[],"resources":[],"quiz":{"question":"Según el cierre del curso, ¿qué se vuelve más importante a medida que subes en la \"escalera de autonomía\" (de un prompt suelto a un equipo completo de agentes)?","options":["Nada cambia, la supervisión importa igual en todos los niveles","La supervisión humana real, los presupuestos claros y el hábito de revisar antes de confiar ciegamente","Ya no hace falta ninguna supervisión en absoluto","Solo importa la velocidad de respuesta"],"correctIndex":1},"id":6,"order":6}]',
  '{}'::jsonb
)
on conflict (id) do update set
  title = excluded.title, description = excluded.description, ai_instructions = excluded.ai_instructions,
  icon = excluded.icon, color = excluded.color, category = excluded.category,
  subcategory = excluded.subcategory, difficulty = excluded.difficulty, locked = excluded.locked,
  modules = excluded.modules, translations = excluded.translations, updated_at = now();

insert into public.courses
  (id, title, description, ai_instructions, icon, color, category, subcategory, difficulty, locked, modules, translations)
values (
  'course-fuentes-abiertas', 'Fundamentos del Código Abierto', 'Las reglas generales que aplican a CUALQUIER proyecto de código abierto: qué es realmente, cómo leer un repositorio que nunca has visto, licencias explicadas sin jerga legal, el flujo de contribución con Pull Requests, y cómo se sostiene (o no) un proyecto del que depende medio internet. Con OpenClaw y Paperclip como ejemplos reales a lo largo del curso.', 'Eres el Mago, profesor de la Escuela de Programación de Oliver Academy, guiando el curso "Fundamentos del Código Abierto". Explica conceptos legales de licencias con precisión pero sin jerga, y siempre aclara que no eres un abogado — para decisiones legales importantes sobre licenciamiento, recomienda consultar una fuente especializada o un profesional. Anima al alumno a mirar repositorios reales mientras aprende, no solo a leer teoría.',
  '📖', '#84cc16', 'Programación', 'Código Abierto', 'principiante', false,
  '[{"type":"text","title":"Bienvenida: las reglas que aplican a cualquier proyecto","description":"Un curso de fundamentos generales, no de un proyecto específico.","content":"\n<h2>Por qué este curso es distinto a \"OpenClaw\" y \"Paperclip\"</h2>\n<p>Los cursos <em>OpenClaw</em> y <em>Paperclip</em> de esta escuela te enseñaron dos proyectos específicos, de principio a fin. Este curso da un paso atrás: las reglas, hábitos y conceptos que aplican a <strong>cualquier</strong> proyecto de código abierto que encuentres — para que sepas moverte con confianza en un repositorio que jamás has visto, sea cual sea.</p>\n\n<h2>El mapa del curso</h2>\n<table>\n<tr><th>Parte</th><th>Qué vas a aprender</th></tr>\n<tr><td>1. Qué es realmente el código abierto</td><td>Más allá de \"el código es público\".</td></tr>\n<tr><td>2. Licencias, sin jerga legal</td><td>Qué puedes y no puedes hacer con el código de otros.</td></tr>\n<tr><td>3. Leer un repositorio desconocido</td><td>Un método para orientarte en minutos, no horas.</td></tr>\n<tr><td>4. El flujo de contribución</td><td>De un fork a un Pull Request aceptado.</td></tr>\n<tr><td>5. Sostenibilidad y comunidad</td><td>Cómo (y por qué a veces no) se sostiene un proyecto del que depende medio internet.</td></tr>\n</table>\n\n<div class=\"tip\">\n💡 A lo largo del curso vamos a usar <strong>OpenClaw</strong> y <strong>Paperclip</strong> (los proyectos de los dos cursos anteriores) como ejemplos reales y concretos — si ya los tomaste, vas a reconocer varios de sus detalles aquí, ahora vistos desde la perspectiva de las reglas generales.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿En qué se diferencia este curso de \"OpenClaw\" y \"Paperclip\"?","options":["Es exactamente el mismo contenido repetido","Este curso enseña las reglas y hábitos GENERALES que aplican a cualquier proyecto de código abierto, no la arquitectura específica de un solo proyecto","Este curso no tiene ninguna relación con código abierto","Solo sirve para proyectos escritos en un lenguaje específico"],"correctIndex":1},"id":0,"order":0},{"type":"text","title":"Qué es realmente el código abierto","description":"Más allá de \"puedo ver el código\" — las cuatro libertades, otra vez, aplicadas.","content":"\n<h2>Código público no es lo mismo que código abierto</h2>\n<p>Que puedas <strong>ver</strong> el código de un proyecto no significa automáticamente que sea código abierto en el sentido completo. Como viste en <em>Historia de Linux</em>, el software libre y el código abierto se definen por <strong>libertades</strong> concretas: poder ejecutarlo, estudiarlo, modificarlo y redistribuirlo — no solo mirarlo.</p>\n\n<h2>La definición práctica de la Open Source Initiative</h2>\n<p>La <strong>Open Source Initiative (OSI)</strong>, que viste también en <em>Historia de Linux</em>, mantiene una definición formal de qué licencias califican como \"código abierto\" de verdad. En la práctica, para que un proyecto sea código abierto necesita:</p>\n<table>\n<tr><th>Requisito</th><th>En otras palabras</th></tr>\n<tr><td>Código fuente disponible</td><td>No solo el programa compilado, sino el código que un humano puede leer.</td></tr>\n<tr><td>Redistribución libre</td><td>Puedes compartir copias, incluso comercialmente.</td></tr>\n<tr><td>Permite obras derivadas</td><td>Puedes modificarlo y distribuir tu versión modificada.</td></tr>\n<tr><td>Sin discriminación</td><td>No puede prohibir el uso a ciertas personas, grupos o campos de aplicación.</td></tr>\n</table>\n\n<h2>Código abierto no siempre significa \"sin dueño\"</h2>\n<p>Un proyecto de código abierto puede tener una empresa detrás (como Paperclip Labs, Inc. con Paperclip), una fundación sin fines de lucro (como la OpenClaw Foundation), o ser mantenido por voluntarios individuales sin ninguna organización formal. \"Código abierto\" describe la <strong>licencia</strong> del código, no quién lo financia ni quién toma las decisiones del proyecto.</p>\n\n<h2>\"Disponible en GitHub\" no es una licencia</h2>\n<div class=\"warn\">\n⚠️ Que un repositorio esté público en GitHub no significa automáticamente que tengas permiso legal de usarlo, copiarlo o modificarlo — necesitas revisar su <strong>licencia</strong> explícita (normalmente un archivo <code>LICENSE</code> en la raíz del repositorio). Sin una licencia clara, la ley por defecto protege al autor y tú, técnicamente, no tienes permisos automáticos — el siguiente módulo profundiza en esto.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué \"puedo ver el código en GitHub\" no es lo mismo que \"es código abierto\"?","options":["Es exactamente lo mismo, no hay diferencia","Ver el código no te da automáticamente permiso legal de usarlo, copiarlo o modificarlo — eso depende de la licencia explícita del proyecto","GitHub solo aloja proyectos de código cerrado","El código abierto nunca se sube a GitHub"],"correctIndex":1},"id":1,"order":1},{"type":"text","title":"Licencias, sin jerga legal","description":"Copyleft vs. permisivas, y cómo identificar cuál tiene un proyecto en segundos.","content":"\n<h2>Repaso rápido: las dos grandes familias</h2>\n<p>Como viste en <em>Historia de Linux</em>, las licencias de código abierto se dividen, a grandes rasgos, en dos familias:</p>\n<table>\n<tr><th>Familia</th><th>Ejemplos</th><th>Idea central</th></tr>\n<tr><td><strong>Copyleft</strong></td><td>GPL, AGPL, LGPL</td><td>Si distribuyes una versión modificada, debe seguir siendo de código abierto, bajo la misma licencia.</td></tr>\n<tr><td><strong>Permisivas</strong></td><td>MIT, Apache 2.0, BSD</td><td>Puedes hacer casi lo que quieras, incluso cerrar el código en un producto comercial — solo debes conservar el aviso de autoría.</td></tr>\n</table>\n\n<h2>Ejemplos reales que ya conoces</h2>\n<table>\n<tr><th>Proyecto</th><th>Licencia</th><th>Qué significa en la práctica</th></tr>\n<tr><td>Paperclip</td><td>MIT</td><td>Puedes usarlo, modificarlo, e incluso venderlo como parte de otro producto, siempre que conserves el aviso de licencia original.</td></tr>\n<tr><td>Linux (el kernel)</td><td>GPL v2</td><td>Cualquier dispositivo que lo distribuya con modificaciones debe ofrecer el código fuente de esas modificaciones.</td></tr>\n</table>\n\n<h2>Cómo identificar la licencia de un proyecto en segundos</h2>\n<ol>\n<li>Busca un archivo llamado <code>LICENSE</code> o <code>LICENSE.md</code> en la raíz del repositorio.</li>\n<li>Si no está, revisa el archivo <code>README</code> — muchos proyectos mencionan su licencia ahí.</li>\n<li>En GitHub, la barra lateral derecha de cualquier repositorio suele mostrar la licencia detectada automáticamente.</li>\n<li>Si de verdad no encuentras ninguna licencia, <strong>asume que no tienes permisos automáticos</strong> de uso o redistribución — escríbele al autor si necesitas usarlo formalmente.</li>\n</ol>\n\n<h2>Preguntas prácticas antes de usar código de otros</h2>\n<table>\n<tr><th>Pregunta</th><th>Por qué importa</th></tr>\n<tr><td>¿Voy a usarlo en un producto comercial?</td><td>Algunas licencias tienen condiciones distintas para uso comercial.</td></tr>\n<tr><td>¿Voy a modificarlo y redistribuirlo?</td><td>Una licencia copyleft te obligaría a mantener esa misma licencia en tu versión.</td></tr>\n<tr><td>¿Necesito conservar avisos de autoría?</td><td>Casi todas las licencias, incluso las permisivas, lo exigen.</td></tr>\n</table>\n\n<div class=\"warn\">\n⚠️ No soy abogado, y este curso tampoco lo es: para decisiones legales importantes sobre licenciamiento (especialmente en un producto comercial), consulta con un profesional o usa herramientas especializadas como choosealicense.com como punto de partida, no como consejo legal definitivo.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es la diferencia central entre una licencia copyleft (como GPL) y una permisiva (como MIT)?","options":["No hay ninguna diferencia real entre ellas","La copyleft exige que las versiones modificadas distribuidas sigan siendo de código abierto; la permisiva permite incluso cerrar el código, solo exigiendo conservar el aviso de autoría","Las permisivas nunca se pueden usar comercialmente","La copyleft prohíbe totalmente modificar el código"],"correctIndex":1},"id":2,"order":2},{"type":"text","title":"Cómo leer un repositorio que nunca has visto","description":"Un método de cinco minutos para orientarte en cualquier proyecto nuevo.","content":"\n<h2>El problema: llegar a un repositorio y no saber por dónde empezar</h2>\n<p>Abrir el repositorio de un proyecto grande por primera vez puede ser abrumador — cientos de archivos, carpetas con nombres que no conoces. Este método te da un orden de exploración que funciona con casi cualquier proyecto.</p>\n\n<h2>El método de cinco pasos</h2>\n<ol>\n<li><strong>Lee el README primero, completo.</strong> Casi siempre explica qué hace el proyecto, cómo instalarlo, y a veces cómo está organizado.</li>\n<li><strong>Mira la estructura de carpetas de nivel superior</strong>, sin entrar todavía a ninguna. Los nombres ya te dicen mucho: <code>docs</code> (documentación), <code>tests</code> (pruebas), <code>src</code> o <code>apps</code> (el código principal).</li>\n<li><strong>Busca un archivo CONTRIBUTING.md</strong> — casi siempre explica exactamente cómo está organizado el proyecto para quien quiere colaborar.</li>\n<li><strong>Revisa el archivo de configuración de dependencias</strong> (<code>package.json</code> en proyectos de JavaScript/Node, por ejemplo) — te dice qué otras herramientas y librerías usa el proyecto.</li>\n<li><strong>Busca el punto de entrada</strong> — el archivo desde donde arranca todo (a menudo mencionado en el README o en la configuración de arranque).</li>\n</ol>\n\n<h2>Aplicado a un ejemplo real: la estructura de OpenClaw</h2>\n<p>Como viste en el curso <em>OpenClaw</em> de esta escuela, su repositorio tiene carpetas como <code>apps</code> (las aplicaciones), <code>crates</code> (componentes escritos en Rust), y <code>config</code> — con solo leer esos nombres, ya sabes que es un proyecto con varias aplicaciones relacionadas y al menos parte del código en Rust, antes de abrir un solo archivo de código.</p>\n\n<h2>No intentes entenderlo todo de golpe</h2>\n<div class=\"tip\">\n💡 Nadie lee un proyecto grande de arriba a abajo de una sola sentada — ni siquiera sus propios mantenedores tienen memorizado cada archivo. Entra con una pregunta específica (\"¿cómo maneja los errores?\", \"¿dónde se conecta a la base de datos?\") en vez de intentar \"entender todo el proyecto\" de una vez.\n</div>\n\n<h2>Usa la IA como guía, no como sustituto de leer</h2>\n<p>Puedes pegarle a Claude o a tu asistente de IA un archivo específico y pedirle que te explique qué hace línea por línea (como viste en <em>El Gran Repositorio de Prompts</em>) — un excelente atajo para entender más rápido, aunque no reemplaza tu propio criterio para juzgar si el código está bien diseñado.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es el primer paso recomendado al explorar un repositorio de código abierto que nunca has visto?","options":["Leer cada archivo de código en orden alfabético","Leer el README completo primero — casi siempre explica qué hace el proyecto y cómo está organizado","Modificar el código inmediatamente sin leer nada","Buscar solo los archivos de configuración, ignorando el resto"],"correctIndex":1},"id":3,"order":3},{"type":"text","title":"El flujo de contribución: de un fork a un Pull Request aceptado","description":"El proceso paso a paso, con las reglas no escritas que hacen que un PR se acepte.","content":"\n<h2>El flujo técnico, repaso</h2>\n<p>Si tomaste <em>Git y GitHub: de Cero a Experto</em> de esta escuela, este flujo ya te resulta familiar — aquí lo revisas enfocado específicamente en contribuir a un proyecto que <strong>no es tuyo</strong>:</p>\n<ol>\n<li><strong>Fork:</strong> creas tu propia copia del repositorio en tu cuenta.</li>\n<li><strong>Clona</strong> tu fork a tu computadora.</li>\n<li>Crea una <strong>rama</strong> nueva y descriptiva para tu cambio (no trabajes directamente en <code>main</code>).</li>\n<li>Haz tu cambio, con <strong>commits</strong> pequeños y mensajes claros.</li>\n<li><strong>Push</strong> a tu fork, y abre un <strong>Pull Request</strong> hacia el repositorio original.</li>\n<li>Responde a la revisión — casi ningún PR se acepta sin al menos una ronda de comentarios.</li>\n</ol>\n\n<h2>Las reglas NO escritas que aumentan tus probabilidades de éxito</h2>\n<table>\n<tr><th>Regla no escrita</th><th>Por qué importa</th></tr>\n<tr><td>Un PR pequeño y enfocado, no uno gigante</td><td>Un cambio de 500 líneas que toca 20 archivos es mucho más difícil (y desalentador) de revisar que uno de 20 líneas con un propósito claro.</td></tr>\n<tr><td>Explica el \"por qué\", no solo el \"qué\"</td><td>El código ya muestra qué cambiaste; la descripción del PR debe explicar por qué era necesario.</td></tr>\n<tr><td>Para cambios grandes, pregunta primero</td><td>Abre un issue o pregunta en la comunidad antes de invertir horas en algo que quizás el proyecto no quiere aceptar.</td></tr>\n<tr><td>Sigue el estilo de código existente</td><td>Consistencia importa más que tu preferencia personal de formato.</td></tr>\n<tr><td>Sé paciente con la revisión</td><td>Los mantenedores suelen ser voluntarios o tener tiempo limitado — una respuesta puede tardar días o semanas.</td></tr>\n</table>\n\n<h2>\"Good first issue\": tu punto de entrada</h2>\n<p>Muchos proyectos activos (incluidos OpenClaw y Paperclip) etiquetan issues pequeños y bien definidos como <strong>\"good first issue\"</strong> — pensados específicamente para que alguien nuevo en el proyecto tenga un punto de entrada claro, sin necesitar entender todo el sistema de antemano.</p>\n\n<div class=\"tip\">\n💡 Tu primera contribución no tiene que ser código. Corregir un error de tipografía en la documentación, mejorar un ejemplo confuso, o traducir un archivo, son contribuciones reales y bienvenidas — y una forma excelente de aprender el flujo completo antes de intentar algo más grande.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué un Pull Request pequeño y enfocado tiene más probabilidades de ser aceptado que uno gigante?","options":["Los PR grandes siempre se rechazan automáticamente","Un cambio pequeño y con un propósito claro es mucho más fácil y rápido de revisar para los mantenedores","El tamaño del PR nunca importa","Los proyectos solo aceptan PRs de una sola línea"],"correctIndex":1},"id":4,"order":4},{"type":"text","title":"Cómo se sostiene (o no) un proyecto de código abierto","description":"El dinero, el tiempo y el agotamiento detrás del software del que depende medio internet.","content":"\n<h2>Una pregunta incómoda pero importante</h2>\n<p>Mucho software crítico de internet depende de proyectos de código abierto mantenidos por muy pocas personas, a veces sin ninguna compensación económica. Entender cómo (y a veces cómo NO) se sostienen estos proyectos te da una perspectiva importante como usuario y posible contribuidor.</p>\n\n<h2>Modelos de sostenibilidad, con ejemplos reales</h2>\n<table>\n<tr><th>Modelo</th><th>Ejemplo</th><th>Cómo funciona</th></tr>\n<tr><td>Fundación sin fines de lucro</td><td>OpenClaw Foundation</td><td>Recibe donaciones de empresas y organizaciones (Amazon, Red Hat, GitHub, NVIDIA, entre otros donantes mencionados en el proyecto) que financian el trabajo sin ser dueñas del proyecto.</td></tr>\n<tr><td>Empresa con producto de código abierto</td><td>Paperclip Labs, Inc.</td><td>Una empresa mantiene el proyecto abierto, y puede ofrecer servicios adicionales de pago (soporte, alojamiento) sobre la base gratuita.</td></tr>\n<tr><td>Patrocinio individual</td><td>Muchos proyectos pequeños</td><td>Plataformas como GitHub Sponsors o Patreon permiten donaciones directas a mantenedores individuales.</td></tr>\n<tr><td>Voluntariado puro</td><td>Buena parte del ecosistema</td><td>Sin ningún financiamiento formal — mantenido en tiempo libre, por pasión o necesidad propia.</td></tr>\n</table>\n\n<h2>El riesgo real: el agotamiento de mantenedores</h2>\n<p>Un problema documentado y recurrente en el ecosistema de código abierto: proyectos usados por millones de personas (o por empresas enormes) mantenidos por una sola persona sin compensación, que termina agotada respondiendo issues, revisando PRs, y arreglando errores sin ayuda suficiente. Cuando esa persona se va, el proyecto puede quedar sin mantenimiento de un día para otro, afectando a todo quien dependía de él.</p>\n\n<h2>Cómo puedes ayudar a la sostenibilidad, incluso sin programar</h2>\n<ul>\n<li>Patrocina económicamente los proyectos que usas y valoras, si puedes.</li>\n<li>Reporta errores de forma clara y útil, en vez de generar más trabajo innecesario para el mantenedor.</li>\n<li>Responde preguntas de otros usuarios en los foros o Discord del proyecto — le quita carga directa al mantenedor principal.</li>\n<li>Da crédito público al proyecto cuando lo uses, ayudando a que consiga más apoyo y visibilidad.</li>\n</ul>\n\n<div class=\"tip\">\n💡 La próxima vez que uses una herramienta gratuita de código abierto que te ahorra horas de trabajo, considera si puedes devolver algo — aunque sea un reporte de error bien escrito o una estrella en el repositorio.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es un riesgo real y documentado en el ecosistema de código abierto, según esta clase?","options":["Que el código abierto siempre tiene financiamiento garantizado de por vida","El agotamiento de mantenedores: proyectos usados por millones de personas mantenidos por muy pocas personas sin compensación adecuada","Que nadie usa realmente software de código abierto","Que el código abierto siempre es más lento que el código cerrado"],"correctIndex":1},"id":5,"order":5},{"type":"text","title":"Elige la licencia correcta para tu propio proyecto","description":"Cuando pasas de usuario/contribuidor a autor: cómo decidir con criterio.","content":"\n<h2>Sin licencia, nadie puede usar legalmente tu código</h2>\n<div class=\"warn\">\n⚠️ Si publicas código en GitHub sin ningún archivo de licencia, por defecto <strong>no</strong> le estás dando permiso legal a nadie de usarlo, modificarlo o redistribuirlo — aunque sea público. Si quieres que otros lo usen, necesitas elegir y agregar una licencia explícitamente.\n</div>\n\n<h2>Preguntas para decidir qué licencia elegir</h2>\n<table>\n<tr><th>Pregunta</th><th>Si la respuesta es \"sí\"...</th></tr>\n<tr><td>¿Me importa que las versiones modificadas de mi código sigan siendo abiertas?</td><td>Considera una licencia copyleft (GPL).</td></tr>\n<tr><td>¿Quiero que empresas puedan usar mi código libremente, incluso en productos cerrados?</td><td>Considera una licencia permisiva (MIT, Apache 2.0).</td></tr>\n<tr><td>¿Necesito protección explícita de patentes?</td><td>Apache 2.0 incluye cláusulas de patentes que MIT no tiene.</td></tr>\n<tr><td>¿Es un proyecto pequeño y solo quiero algo simple?</td><td>MIT es, por lejos, la licencia permisiva más usada y sencilla de entender.</td></tr>\n</table>\n\n<h2>Una herramienta práctica</h2>\n<p><strong>choosealicense.com</strong>, mantenido por GitHub, es un buen punto de partida para comparar licencias comunes en lenguaje simple, con ejemplos de qué proyectos las usan.</p>\n\n<h2>Aplícalo en la práctica</h2>\n<p>En GitHub, al crear un repositorio nuevo, hay una opción para agregar una licencia directamente desde una lista de las más comunes — no necesitas escribir el texto legal tú mismo, solo elegir la que se ajuste a tus objetivos.</p>\n\n<div class=\"tip\">\n💡 Piensa en la elección de licencia como una decisión de producto, no solo legal: ¿qué comportamiento quieres fomentar en quien use tu código? Esa pregunta suele guiarte a la respuesta correcta más rápido que memorizar cláusulas legales.\n</div>\n\n<h2>Cierre del curso</h2>\n<p>Con este curso ya tienes las reglas generales: qué es realmente el código abierto, cómo identificar y entender una licencia, cómo orientarte en cualquier repositorio nuevo, el flujo completo de contribución, y una mirada honesta a cómo (y por qué a veces no) se sostienen estos proyectos. Aplícalo la próxima vez que abras un repositorio — el de OpenClaw, el de Paperclip, o cualquier otro que te encuentres.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué pasa legalmente si publicas código en un repositorio público de GitHub SIN ningún archivo de licencia?","options":["Automáticamente se vuelve de dominio público y cualquiera puede hacer lo que quiera con él","Por defecto, no le das permiso legal a nadie de usarlo, modificarlo o redistribuirlo, aunque el código sea visible","GitHub le asigna automáticamente la licencia MIT","No es posible publicar código sin licencia en GitHub"],"correctIndex":1},"id":6,"order":6}]',
  '{}'::jsonb
)
on conflict (id) do update set
  title = excluded.title, description = excluded.description, ai_instructions = excluded.ai_instructions,
  icon = excluded.icon, color = excluded.color, category = excluded.category,
  subcategory = excluded.subcategory, difficulty = excluded.difficulty, locked = excluded.locked,
  modules = excluded.modules, translations = excluded.translations, updated_at = now();

insert into public.courses
  (id, title, description, ai_instructions, icon, color, category, subcategory, difficulty, locked, modules, translations)
values (
  'course-historia-agentes-ia', 'Historia de los Agentes de IA Autónomos', 'De los primeros experimentos virales que ataban un modelo de lenguaje a un bucle de "piensa y actúa", a los asistentes personales de código abierto y las herramientas que coordinan equipos completos de agentes. La historia reciente y en curso de cómo la IA pasó de responder a actuar.', 'Eres el Mago, profesor de la Escuela de Programación de Oliver Academy, guiando el curso "Historia de los Agentes de IA Autónomos". Este es un tema MUY reciente (2023 en adelante) y en desarrollo activo — sé especialmente cuidadoso en distinguir hechos bien documentados de percepciones o hype del momento, y aclara siempre que tu conocimiento tiene una fecha de corte y que el panorama sigue cambiando. Nunca inventes fechas o cifras exactas que no recuerdes con certeza — di que no estás seguro en vez de aproximar como si fuera un hecho.',
  '🤖', '#0ea5e9', 'Programación', 'Código Abierto', 'intermedio', false,
  '[{"type":"text","title":"Bienvenida: la historia más reciente de esta escuela","description":"De \"responder preguntas\" a \"hacer el trabajo\" — una transición que está ocurriendo mientras tomas este curso.","content":"\n<h2>Un tipo de historia distinto</h2>\n<p>Los demás cursos de historia de esta escuela (<em>Historia de la Inteligencia Artificial</em>, <em>Historia de Linux</em>) cubren décadas, con hechos bien documentados y asentados. Este curso es distinto: cubre apenas un puñado de años (2023 en adelante), un periodo tan reciente que todavía está <strong>ocurriendo</strong> mientras lo estudias. Trátalo con esa perspectiva.</p>\n\n<h2>El hilo conductor: de responder a actuar</h2>\n<p>Como viste en <em>Actualidad de la IA</em>, la tendencia central de este periodo es el paso de <strong>chatbots que responden</strong> a <strong>agentes que actúan</strong> — este curso cuenta esa historia con más detalle: quién empezó a experimentar con esto, qué proyectos marcaron el camino, y cómo llegamos a herramientas como OpenClaw y Paperclip, que ya conoces de los cursos anteriores.</p>\n\n<h2>El mapa del curso</h2>\n<table>\n<tr><th>Parte</th><th>Qué vas a ver</th></tr>\n<tr><td>1. Los primeros experimentos virales</td><td>Cuando \"atar\" un modelo a un bucle de acción se volvió una idea popular.</td></tr>\n<tr><td>2. Los agentes de código</td><td>De sugerir líneas sueltas a resolver tareas de programación completas.</td></tr>\n<tr><td>3. Asistentes personales siempre activos</td><td>El salto de la terminal a tus apps de mensajería de siempre.</td></tr>\n<tr><td>4. La capa de orquestación</td><td>Cuando coordinar varios agentes se volvió su propio problema por resolver.</td></tr>\n<tr><td>5. Hacia dónde parece ir esto</td><td>Con toda la humildad que exige predecir un campo que cambia cada mes.</td></tr>\n</table>\n\n<div class=\"warn\">\n⚠️ Más que ningún otro curso de esta escuela, aquí es fundamental recordar: lo que leas puede haber cambiado ya para cuando lo leas. Usa este curso para entender el <strong>patrón</strong> de cómo llegamos hasta aquí, no como una lista definitiva y final de nombres de productos.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es el hilo conductor de este curso?","options":["La historia completa de la informática desde 1950","El paso, muy reciente, de \"chatbots que responden\" a \"agentes que actúan\" de forma cada vez más autónoma","Solo la historia de una empresa específica","La historia de los videojuegos"],"correctIndex":1},"id":0,"order":0},{"type":"text","title":"Los primeros experimentos: atar un modelo a un bucle","description":"La idea simple (y viral) detrás de los primeros \"agentes autónomos\" de 2023.","content":"\n<h2>Una idea sorprendentemente simple</h2>\n<p>La idea central de un agente autónomo temprano es, en el fondo, muy simple: en vez de que una persona converse con el modelo mensaje por mensaje, se le da un objetivo general, y un programa alrededor del modelo lo pone en un <strong>bucle</strong>: el modelo decide qué hacer, el programa ejecuta esa acción (buscar algo, escribir un archivo, ejecutar un comando), le devuelve el resultado al modelo, y el modelo decide el siguiente paso — repitiendo esto una y otra vez hasta considerar terminado el objetivo, sin que un humano intervenga en cada paso individual.</p>\n\n<h2>2023: el año en que la idea se volvió viral</h2>\n<p>A principios de 2023, poco después de que GPT-4 estuviera disponible (como viste en <em>Historia de la IA</em>), varios proyectos de código abierto que implementaban esta idea de \"modelo en bucle con un objetivo\" se volvieron extremadamente populares muy rápido, generando una enorme ola de interés y experimentación sobre \"agentes autónomos de IA\" en toda la comunidad de desarrolladores — mucha gente probándolos por primera vez, con resultados que iban de sorprendentes a decepcionantes.</p>\n\n<h2>Las limitaciones reales de esa primera ola</h2>\n<table>\n<tr><th>Problema común</th><th>Por qué pasaba</th></tr>\n<tr><td>Bucles improductivos</td><td>El agente repetía variaciones de la misma acción fallida sin darse cuenta, gastando cómputo sin avanzar.</td></tr>\n<tr><td>Pérdida del objetivo original</td><td>En tareas largas, el \"hilo\" del objetivo inicial se perdía o se distorsionaba con cada paso.</td></tr>\n<tr><td>Sin verificación real</td><td>El agente podía \"creer\" que había completado una tarea sin haberla completado correctamente.</td></tr>\n<tr><td>Costo elevado</td><td>Cada paso del bucle consumía llamadas al modelo, y las tareas largas podían salir caras.</td></tr>\n</table>\n<p>Estas limitaciones son, en gran medida, la razón por la que los cursos de <em>Actualidad de la IA</em> y <em>Paperclip</em> insisten tanto en presupuestos y puntos de aprobación humana — son lecciones aprendidas directamente de esta primera ola.</p>\n\n<h2>Por qué importó de todas formas</h2>\n<p>Aunque esos primeros proyectos eran imperfectos en la práctica, demostraron algo importante: que la idea de \"un modelo actuando en bucle hacia un objetivo\" era técnicamente posible y capturaba la imaginación de miles de desarrolladores a la vez — sembrando el interés que, con el tiempo, maduraría en herramientas mucho más confiables.</p>\n\n<div class=\"tip\">\n💡 Este patrón — una idea imperfecta pero viral que abre camino a versiones mucho mejores después — ya lo viste en <em>Historia de la IA</em> con las redes neuronales de los 80: a veces el primer intento imperfecto es lo que demuestra que vale la pena seguir invirtiendo en la idea.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál era la idea central detrás de los primeros \"agentes autónomos\" populares de 2023?","options":["Un chatbot que solo responde una pregunta a la vez","Un modelo puesto en un bucle: decide una acción, un programa la ejecuta, el resultado vuelve al modelo, y repite hasta considerar terminado el objetivo","Un modelo que solo genera imágenes","Un sistema que reemplaza por completo a los programadores humanos"],"correctIndex":1},"id":1,"order":1},{"type":"text","title":"Los agentes de código: de sugerir líneas a resolver tareas completas","description":"Cómo la programación fue de las primeras áreas en madurar esta idea de agentes.","content":"\n<h2>Por qué programar fue un terreno natural para los agentes</h2>\n<p>La programación tiene una ventaja única para los agentes de IA: los resultados se pueden <strong>verificar automáticamente</strong> — el código o funciona (pasa las pruebas, compila, hace lo que debía) o no funciona. Esa retroalimentación clara y objetiva hace que sea mucho más fácil que un agente sepa si va por buen camino, comparado con tareas más subjetivas.</p>\n\n<h2>La evolución en etapas, revisitada</h2>\n<p>Como viste en <em>Actualidad de la IA</em>, la programación asistida por IA pasó por etapas: del autocompletado dentro del editor, a un chat conversacional donde copiabas y pegabas código manualmente, hasta agentes que trabajan directamente sobre un proyecto completo — leyendo varios archivos, haciendo cambios coordinados, y ejecutando pruebas por sí mismos.</p>\n\n<h2>Herramientas que marcaron esta transición</h2>\n<table>\n<tr><th>Tipo de herramienta</th><th>Ejemplos que ya conoces</th></tr>\n<tr><td>Agentes de código de los laboratorios de modelos</td><td>Claude Code (Anthropic), Codex (OpenAI) — viste el primero a fondo en <em>Domina Claude</em>.</td></tr>\n<tr><td>Editores con IA integrada como agente</td><td>Herramientas como Cursor, que integran capacidades de agente directamente en el flujo de edición.</td></tr>\n<tr><td>Agentes de código abierto especializados</td><td>Proyectos de la comunidad enfocados específicamente en resolver tareas de programación de forma autónoma.</td></tr>\n</table>\n\n<h2>Lo que estos agentes demostraron</h2>\n<p>Los agentes de código ayudaron a demostrar, con evidencia concreta y verificable (pruebas que pasan, código que funciona), que un modelo de lenguaje puede completar tareas de varios pasos con bastante fiabilidad cuando tiene <strong>retroalimentación clara</strong> en cada paso — una lección que después se extendió a otros dominios, aunque con más dificultad al no tener siempre una forma tan objetiva de verificar el éxito.</p>\n\n<div class=\"tip\">\n💡 Si tomaste <em>Domina Claude</em>, ya viste de primera mano cómo funciona un agente de código moderno — este módulo te da el contexto histórico de por qué la programación fue, específicamente, donde esta tecnología maduró primero.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué la programación fue un terreno particularmente favorable para que maduraran los primeros agentes de IA confiables?","options":["Porque programar es más fácil que cualquier otra tarea","Porque los resultados se pueden verificar automáticamente (el código funciona o no), dándole al agente retroalimentación clara y objetiva en cada paso","Porque no requiere ningún tipo de supervisión humana","Porque los agentes de código no cometen errores"],"correctIndex":1},"id":2,"order":2},{"type":"text","title":"De la terminal a tus apps de siempre: los asistentes personales","description":"Cuando los agentes dejaron de vivir solo en una terminal de programador.","content":"\n<h2>Un salto de audiencia, no solo de tecnología</h2>\n<p>Los primeros agentes autónomos vivían casi exclusivamente en la terminal, pensados para desarrolladores cómodos con la línea de comandos. El siguiente paso natural fue llevar esa misma capacidad a donde la gente <strong>ya</strong> pasa su tiempo: WhatsApp, Telegram, Discord, Slack — las mismas apps de mensajería de todos los días, no una herramienta técnica aparte.</p>\n\n<h2>OpenClaw como ejemplo de esta ola</h2>\n<p>Como viste en el curso <em>OpenClaw</em> de esta escuela, ese proyecto representa exactamente este movimiento: un asistente capaz de actuar (no solo responder), que corre en tu propio hardware por privacidad, y que te encuentra en los canales que ya usas, en vez de obligarte a abrir una interfaz nueva y aprenderla desde cero.</p>\n\n<h2>Por qué este cambio de canal importa tanto</h2>\n<table>\n<tr><th>Antes</th><th>Después</th></tr>\n<tr><td>Necesitabas saber usar una terminal.</td><td>Le escribes como a cualquier contacto en tu app de mensajería favorita.</td></tr>\n<tr><td>El asistente era una herramienta técnica aparte de tu vida digital.</td><td>El asistente vive dentro de tu flujo normal de comunicación.</td></tr>\n<tr><td>Uso limitado a desarrolladores y entusiastas técnicos.</td><td>Accesible para cualquier persona que ya usa WhatsApp o Telegram.</td></tr>\n</table>\n\n<h2>El otro lado de la moneda: privacidad y control</h2>\n<p>Llevar un asistente con capacidad de actuar a tus canales personales de mensajería plantea preguntas de privacidad más directas que un chatbot de escritorio — por eso, como viste en el curso de <em>OpenClaw</em>, el diseño de este tipo de herramientas pone tanto énfasis en que el estado y las credenciales vivan en tu propio hardware, y en tratar los mensajes entrantes como no confiables por defecto.</p>\n\n<div class=\"tip\">\n💡 Este patrón — llevar una tecnología de un círculo técnico especializado al uso cotidiano de cualquier persona — es exactamente el mismo que viste con ChatGPT en <em>Historia de la IA</em>: la tecnología de fondo ya existía en formas más limitadas; lo que cambia todo es hacerla accesible en el lugar donde la gente ya está.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué representa el paso de \"agentes solo en la terminal\" a \"agentes en WhatsApp/Telegram/Discord\"?","options":["No representa ningún cambio real","Un salto de audiencia: de herramientas técnicas para desarrolladores a algo accesible para cualquier persona, dentro de las apps que ya usa a diario","Un retroceso tecnológico","Solo un cambio de nombre, sin diferencia funcional"],"correctIndex":1},"id":3,"order":3},{"type":"text","title":"La capa de orquestación: cuando coordinar agentes se volvió su propio problema","description":"De \"tengo un agente\" a \"tengo veinte agentes y no sé qué hace cada uno\".","content":"\n<h2>Un problema que solo aparece a escala</h2>\n<p>Usar un solo agente de IA es manejable — lo ves trabajar, revisas el resultado, listo. El problema nuevo apareció cuando la gente empezó a usar <strong>varios agentes a la vez</strong>, para distintas tareas: de pronto, coordinar quién hace qué, cuánto gasta cada uno, y si alguno se quedó atascado, se volvió un problema en sí mismo — separado del problema original de \"hacer que un agente funcione bien\".</p>\n\n<h2>Paperclip como respuesta a este problema</h2>\n<p>Como viste en el curso <em>Paperclip</em> de esta escuela, ese proyecto nació específicamente para resolver este problema de segundo orden: no \"cómo hago que un agente sea bueno\", sino \"cómo organizo, superviso y controlo el costo de <strong>varios</strong> agentes trabajando a la vez, posiblemente de distintos proveedores\".</p>\n\n<h2>Un patrón que ya conoces de la historia de la computación</h2>\n<p>Este tipo de evolución — una tecnología nueva madura, y después aparece una capa de gestión y coordinación encima de ella — no es nuevo en la historia de la computación:</p>\n<table>\n<tr><th>Tecnología base</th><th>Capa de gestión que apareció después</th></tr>\n<tr><td>Servidores individuales</td><td>Herramientas de orquestación de contenedores (como Kubernetes)</td></tr>\n<tr><td>Empleados individuales en una empresa</td><td>Sistemas de gestión de proyectos y recursos humanos</td></tr>\n<tr><td>Agentes de IA individuales</td><td>Herramientas de orquestación como Paperclip</td></tr>\n</table>\n\n<h2>Por qué esto sugiere que el campo está madurando</h2>\n<p>La aparición de una \"capa de gestión\" dedicada suele ser una señal de que una tecnología pasó de ser un experimento novedoso a algo que la gente usa de forma seria y sostenida — nadie construye herramientas de organigrama y presupuesto para algo que todavía es solo un juguete experimental. El hecho de que existan proyectos como Paperclip sugiere que, para 2025-2026, coordinar varios agentes de IA ya era un problema real y recurrente para suficiente gente como para justificar construir una solución dedicada.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué sugiere la aparición de herramientas de orquestación como Paperclip sobre el estado del campo de los agentes de IA?","options":["Que los agentes de IA fracasaron por completo","Que el uso de agentes de IA maduró lo suficiente como para que coordinar varios a la vez se volviera un problema real y recurrente, que justifica una solución dedicada","Que ya no se necesitan agentes individuales","Que este problema nunca existió antes en la historia de la computación"],"correctIndex":1},"id":4,"order":4},{"type":"text","title":"Hacia dónde parece ir esto (con toda la humildad necesaria)","description":"Tendencias razonables, no predicciones certeras — la diferencia importa.","content":"\n<h2>Por qué esta clase es distinta a una predicción segura</h2>\n<p>Predecir hacia dónde va un campo que cambia cada pocos meses es, por definición, arriesgado. Esta clase no te da certezas — te da <strong>tendencias razonables</strong> a partir de lo que ya viste en este curso, con la honestidad de que podrían no cumplirse exactamente así.</p>\n\n<h2>Tendencias que parecen razonables a partir de lo visto</h2>\n<table>\n<tr><th>Tendencia</th><th>Por qué parece razonable, según lo que ya viste</th></tr>\n<tr><td>Más verificación automática antes de confiar en un agente</td><td>La lección de los bucles improductivos de 2023 (módulo 2) sigue siendo relevante — la confianza se gana con retroalimentación verificable.</td></tr>\n<tr><td>Más capas de gobernanza y presupuesto, no menos</td><td>Paperclip resuelve un problema real; es razonable esperar que ese tipo de herramienta se vuelva más común, no una rareza.</td></tr>\n<tr><td>Agentes cada vez más presentes en canales cotidianos</td><td>El patrón de OpenClaw (llevar la IA a donde la gente ya está) es consistente con cómo se adoptó la tecnología anteriormente (módulo 4).</td></tr>\n<tr><td>Regulación específica para agentes autónomos</td><td>Como viste en <em>Actualidad de la IA</em>, la regulación de IA en general ya está en marcha; es razonable que agentes con capacidad de actuar (no solo responder) reciban atención regulatoria específica.</td></tr>\n</table>\n\n<h2>Lo que este curso NO te puede decir con certeza</h2>\n<ul>\n<li>Qué proyecto específico \"ganará\" en este espacio — los nombres y líderes del mercado cambian rápido.</li>\n<li>Cuándo (o si) los agentes autónomos llegarán a ser tan confiables como para necesitar mínima supervisión humana en tareas importantes.</li>\n<li>Cómo evolucionará exactamente la regulación en cada país.</li>\n</ul>\n\n<div class=\"warn\">\n⚠️ Si en el futuro lees sobre un proyecto nuevo en este espacio que no se menciona en este curso, eso no es un error del curso — es exactamente la naturaleza de estudiar un campo que sigue en movimiento. Usa el patrón que aprendiste aquí (de responder → actuar → coordinar varios agentes) para entender dónde encaja cualquier herramienta nueva que encuentres.\n</div>\n\n<h2>Cierre del curso</h2>\n<p>Viste el arco completo: los primeros experimentos virales e imperfectos, la maduración en el terreno de la programación, el salto a asistentes personales como OpenClaw, y la aparición de la capa de orquestación con Paperclip. Es una historia corta pero densa, y sigue escribiéndose — con las herramientas de esta escuela, ahora tienes el contexto para seguirla entendiendo, no solo reaccionando a cada titular nuevo.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es la actitud correcta al leer sobre un proyecto de agentes de IA muy nuevo que no aparece en este curso?","options":["Asumir que el curso está mal hecho","Reconocer que es normal en un campo que cambia rápido, y usar el patrón aprendido (responder → actuar → coordinar) para entender dónde encaja esa herramienta nueva","Ignorar cualquier información posterior a este curso","Asumir que ningún proyecto nuevo puede ser legítimo"],"correctIndex":1},"id":5,"order":5}]',
  '{}'::jsonb
)
on conflict (id) do update set
  title = excluded.title, description = excluded.description, ai_instructions = excluded.ai_instructions,
  icon = excluded.icon, color = excluded.color, category = excluded.category,
  subcategory = excluded.subcategory, difficulty = excluded.difficulty, locked = excluded.locked,
  modules = excluded.modules, translations = excluded.translations, updated_at = now();

insert into public.courses
  (id, title, description, ai_instructions, icon, color, category, subcategory, difficulty, locked, modules, translations)
values (
  'course-crea-app-ia', 'Crea tu Primera App con IA: Curso Práctico', 'De una idea en una servilleta a una app real, publicada en internet, construida describiéndola en lenguaje natural ("vibe coding"): define tu app, elige un stack simple, escribe tus primeros prompts de construcción, depura con ayuda de IA, guarda datos, pruébala, y publícala gratis. El curso más práctico de la Academia de IA.', 'Eres Oliver, profesor guía de la Escuela de Inteligencia Artificial de Oliver Academy, guiando el curso "Crea tu Primera App con IA". Sé muy práctico y alentador — el objetivo es que el alumno termine con algo real funcionando, no solo teoría. Cuando expliques pasos técnicos, asume que el alumno tiene cero experiencia previa de programación y ve cada paso como su primera vez. Sé honesto sobre las limitaciones del "vibe coding" para proyectos serios con datos reales de usuarios, sin desanimar el aprendizaje.',
  '🚀', '#22c55e', 'Inteligencia Artificial', 'Creación de Apps con IA', 'principiante', false,
  '[{"type":"text","title":"Bienvenida: hoy es más fácil que nunca construir algo real","description":"Por qué este curso existe ahora, y qué vas a tener al terminarlo.","content":"\n<h2>Lo que vas a lograr</h2>\n<p>Al terminar este curso vas a tener una <strong>app web real, funcionando, publicada en internet</strong> — no un ejercicio de práctica que se queda en tu computadora, sino algo con una dirección que puedes compartir con quien quieras. La vas a construir describiéndola en lenguaje natural a un asistente de IA, con tu criterio guiando cada decisión.</p>\n\n<h2>El \"vibe coding\", explicado sin exagerar</h2>\n<p>Como viste en <em>Actualidad de la IA</em>, el <strong>vibe coding</strong> es describir en lenguaje natural lo que quieres construir, dejando que la IA escriba (y a menudo pruebe) la mayor parte del código, mientras tú guías el resultado con tu criterio. Este curso te enseña a hacerlo bien: no es \"pedir una vez y que salga perfecto\" — es un proceso de ida y vuelta, con pasos concretos.</p>\n\n<h2>El mapa del curso: de la idea a internet</h2>\n<table>\n<tr><th>Parte</th><th>Qué vas a hacer</th></tr>\n<tr><td>1. Define tu app</td><td>Una idea clara, en una sola página, antes de escribir nada.</td></tr>\n<tr><td>2. Elige tu stack</td><td>Sin abrumarte con opciones — una elección simple y suficiente.</td></tr>\n<tr><td>3. Tu primer prompt de construcción</td><td>El arranque real, paso a paso.</td></tr>\n<tr><td>4. Depura con IA</td><td>Qué hacer cuando algo (inevitablemente) no funciona.</td></tr>\n<tr><td>5. Dale vida con datos</td><td>Que tu app recuerde información, no solo se vea bonita.</td></tr>\n<tr><td>6. Pruébala de verdad</td><td>Antes de mostrársela a nadie más.</td></tr>\n<tr><td>7. Publícala gratis</td><td>Una dirección real en internet.</td></tr>\n</table>\n\n<div class=\"tip\">\n💡 No necesitas experiencia previa de programación para este curso — sí te va a ayudar mucho haber tomado <em>Trucos y Consejos para Sacarle el Máximo Provecho a la IA</em>, porque vas a usar esos mismos hábitos (contexto, iteración, verificación) constantemente.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué vas a tener al terminar este curso, según la bienvenida?","options":["Solo conocimiento teórico, sin nada construido","Una app web real, funcionando, publicada en internet con una dirección que puedes compartir","Un certificado sin ningún proyecto asociado","Una lista de lecturas para el futuro"],"correctIndex":1},"id":0,"order":0},{"type":"text","title":"Define tu app antes de escribir una sola línea","description":"La página de una hoja que evita que te pierdas a la mitad del proyecto.","content":"\n<h2>El error más común: empezar a construir sin saber qué</h2>\n<p>La tentación es abrir el chat de IA y escribir \"hazme una app de lista de tareas\" de inmediato. El problema: sin definir bien qué necesitas, vas a terminar pidiendo cambios contradictorios a mitad del camino, y el resultado será confuso. Cinco minutos de planeación ahorran horas de confusión después.</p>\n\n<h2>La plantilla de una página</h2>\n<table>\n<tr><th>Pregunta</th><th>Ejemplo de respuesta</th></tr>\n<tr><td><strong>¿Qué problema resuelve?</strong></td><td>\"Olvido las tareas que tengo pendientes para mis cursos.\"</td></tr>\n<tr><td><strong>¿Quién la va a usar?</strong></td><td>\"Solo yo, desde mi teléfono y mi computadora.\"</td></tr>\n<tr><td><strong>¿Cuál es la funcionalidad MÍNIMA para que sea útil?</strong></td><td>\"Agregar una tarea, marcarla como hecha, y que no se borre al cerrar la página.\"</td></tr>\n<tr><td><strong>¿Qué NO necesita tener (todavía)?</strong></td><td>\"No necesito cuentas de usuario, ni compartirla con otros, ni categorías.\"</td></tr>\n<tr><td><strong>¿Cómo se ve el éxito?</strong></td><td>\"La abro mañana y mis tareas siguen ahí.\"</td></tr>\n</table>\n\n<h2>Por qué la columna de \"qué NO necesita tener\" es la más importante</h2>\n<p>El error de principiante más común no es pedir muy poco — es pedir demasiado de una sola vez. Una app con 3 funciones que SÍ funcionan es mucho mejor que una con 15 funciones a medio terminar. Recorta sin miedo — siempre puedes agregar más después de tener lo básico funcionando.</p>\n\n<div class=\"example\">\n<strong>Ejemplo completo de definición:</strong> \"Una app de lista de tareas simple. Solo yo la uso. Puedo agregar una tarea escribiendo su texto, marcarla como completada con un clic, y eliminarla. Mis tareas se guardan aunque cierre la pestaña. No necesito cuentas, ni categorías, ni fechas límite por ahora. Sé que funciona si cierro la pestaña, la vuelvo a abrir, y mis tareas siguen ahí.\"\n</div>\n\n<h2>Tu tarea antes de la siguiente clase</h2>\n<p>Escribe tu propia definición de una página, usando la plantilla de arriba, para una app que tú quieras construir. Puede ser tan simple como quieras — el objetivo de este curso es terminar algo funcionando, no algo ambicioso.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es el error de principiante más común al empezar a construir una app con IA?","options":["Definir muy pocas funciones","Pedir demasiadas funciones de una sola vez, en vez de empezar con lo mínimo indispensable que funcione","Escribir la definición de la app antes de empezar","Usar demasiado tiempo planeando"],"correctIndex":1},"id":1,"order":1},{"type":"text","title":"Elige tu stack sin abrumarte","description":"Las decisiones técnicas mínimas para empezar, explicadas sin jerga innecesaria.","content":"\n<h2>Qué es un \"stack\" y por qué no necesitas saber de todos</h2>\n<p>El <strong>stack</strong> es el conjunto de tecnologías con las que se construye una app. Hay cientos de combinaciones posibles — la buena noticia es que, para tu primera app, una combinación simple y muy probada es más que suficiente, y no necesitas entender cada alternativa que existe.</p>\n\n<h2>La recomendación para este curso</h2>\n<table>\n<tr><th>Pieza</th><th>Elección recomendada para empezar</th><th>Por qué</th></tr>\n<tr><td>Estructura y contenido</td><td>HTML</td><td>El lenguaje más simple y universal para definir qué hay en una página.</td></tr>\n<tr><td>Apariencia</td><td>CSS</td><td>Controla colores, tamaños y diseño — la IA puede generarlo por ti sin que necesites memorizar sintaxis.</td></tr>\n<tr><td>Comportamiento</td><td>JavaScript</td><td>Lo que hace que los botones \"hagan algo\" — agregar tareas, guardarlas, etc.</td></tr>\n<tr><td>Dónde guardar datos (al principio)</td><td><code>localStorage</code> del navegador</td><td>Guarda datos directamente en el navegador del usuario, sin necesitar una base de datos ni un servidor — perfecto para una primera app.</td></tr>\n</table>\n\n<h2>¿Por qué no un \"framework\" más avanzado?</h2>\n<p>Existen herramientas más potentes (React, Vue, y muchas otras) que probablemente ya viste mencionadas si exploraste otros cursos de programación. Son excelentes para proyectos grandes, pero agregan complejidad que no necesitas para tu primera app — HTML, CSS y JavaScript \"planos\" son suficientes, y entenderás mejor lo que la IA genera si empiezas simple.</p>\n\n<h2>Un solo archivo es suficiente para empezar</h2>\n<p>Para tu primera app, todo puede vivir en un solo archivo <code>.html</code> que combina las tres piezas — lo puedes abrir directamente en tu navegador para probarlo, sin instalar nada. Cuando tu app crezca, podrás separar el código en varios archivos, pero no hace falta complicarte desde el día uno.</p>\n\n<div class=\"tip\">\n💡 Si en algún momento quieres ir más allá de este curso, el curso <em>Git y GitHub</em> de esta escuela te prepara para organizar proyectos más grandes con control de versiones — perfecto como siguiente paso después de este.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué se recomienda empezar con HTML, CSS y JavaScript \"planos\" en vez de un framework más avanzado?","options":["Porque los frameworks no existen","Porque son suficientes para una primera app y evitan complejidad innecesaria que dificultaría entender lo que la IA genera","Porque la IA no puede generar código de frameworks","Porque HTML, CSS y JavaScript ya no se usan en la industria"],"correctIndex":1},"id":2,"order":2},{"type":"text","title":"Tu primer prompt de construcción, paso a paso","description":"El arranque real: cómo pedirle a la IA tu primera versión funcional.","content":"\n<h2>El prompt inicial: pon todo el contexto que ya tienes</h2>\n<p>Recuerda tu definición de una página de la clase 2 — ahora la conviertes en tu primer prompt real. Sé específico sobre el stack (de la clase anterior) y pide un solo archivo para empezar:</p>\n\n<div class=\"example\">\n<strong>Prompt inicial de ejemplo:</strong><br>\n<code>Quiero construir una app de lista de tareas simple, en un solo archivo HTML con CSS y JavaScript incluidos (sin archivos separados, sin frameworks). Funciones: agregar una tarea escribiendo texto y presionando Enter, marcar una tarea como completada con un clic (se tacha visualmente), eliminar una tarea con un botón, y que las tareas se guarden en localStorage para que no se pierdan al cerrar la pestaña. Hazlo con un diseño simple y limpio, colores suaves. Dame el código completo del archivo.</code>\n</div>\n\n<h2>Guarda y prueba de inmediato</h2>\n<ol>\n<li>Copia el código que te dio la IA en un archivo nuevo, por ejemplo <code>mi-app.html</code>.</li>\n<li>Ábrelo directamente en tu navegador (doble clic en el archivo, o arrástralo a una pestaña).</li>\n<li>Pruébalo de verdad: agrega una tarea, márcala, ciérralo, vuelve a abrirlo.</li>\n</ol>\n\n<h2>La primera versión casi nunca es perfecta — y está bien</h2>\n<p>Como viste en <em>Trucos y Consejos</em>, la primera respuesta rara vez es la final. Es normal que algo no se vea exactamente como imaginabas, o que falte un detalle. El siguiente paso es <strong>iterar</strong>, no empezar de cero.</p>\n\n<h2>Cómo pedir ajustes específicos</h2>\n<table>\n<tr><th>Lo que ves</th><th>Cómo pedirlo</th></tr>\n<tr><td>El botón de eliminar está en el lugar equivocado</td><td>\"Mueve el botón de eliminar a la derecha de cada tarea, no debajo.\"</td></tr>\n<tr><td>Falta un detalle visual</td><td>\"Agrega un contador que muestre cuántas tareas quedan pendientes.\"</td></tr>\n<tr><td>Algo no funciona como esperabas</td><td>Ve a la siguiente clase — depuración es su propio proceso.</td></tr>\n</table>\n\n<div class=\"tip\">\n💡 Mantén la misma conversación con la IA para todos los ajustes de tu app — así conserva el contexto completo de lo que ya construyó, en vez de que tengas que reexplicar todo desde cero cada vez.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué deberías hacer si la primera versión de tu app no es exactamente como la imaginabas?","options":["Abandonar el proyecto inmediatamente","Seguir en la misma conversación e iterar con ajustes específicos, en vez de empezar de cero","Aceptar la versión imperfecta sin pedir cambios","Cambiar completamente de idea de app"],"correctIndex":1},"id":3,"order":3},{"type":"text","title":"Cuando algo no funciona: depurar con ayuda de IA","description":"El paso que todo el mundo teme, convertido en un proceso simple y repetible.","content":"\n<h2>Un error no es un fracaso — es información</h2>\n<p>Que algo no funcione a la primera es completamente normal, incluso para programadores con años de experiencia. La diferencia entre alguien frustrado y alguien productivo no es \"nunca tener errores\" — es saber qué hacer cuando aparecen.</p>\n\n<h2>El método de tres pasos</h2>\n<ol>\n<li><strong>Describe exactamente qué esperabas vs. qué pasó realmente.</strong> No solo \"no funciona\" — sé específico.</li>\n<li><strong>Si hay un mensaje de error, cópialo completo.</strong> La mayoría de los navegadores muestran errores en las \"herramientas de desarrollador\" (clic derecho → \"Inspeccionar\" → pestaña \"Consola\").</li>\n<li><strong>Pega ambas cosas (descripción + error) en tu conversación con la IA.</strong></li>\n</ol>\n\n<div class=\"example\">\n<strong>Antes (vago, difícil de ayudar):</strong> \"Mi botón no funciona.\"<br>\n<strong>Después (específico, fácil de ayudar):</strong> \"Cuando hago clic en el botón ''Agregar tarea'', no pasa nada — no se agrega ninguna tarea a la lista, y la consola muestra este error: ''Uncaught TypeError: Cannot read properties of null''. Aquí está mi código completo: [pega el código]\"\n</div>\n\n<h2>Cómo encontrar el mensaje de error (consola del navegador)</h2>\n<table>\n<tr><th>Navegador</th><th>Cómo abrir la consola</th></tr>\n<tr><td>Chrome / Edge</td><td>Clic derecho en la página → \"Inspeccionar\" → pestaña \"Console\"</td></tr>\n<tr><td>Firefox</td><td>Clic derecho → \"Inspeccionar\" → pestaña \"Consola\"</td></tr>\n<tr><td>Safari</td><td>Activa el menú \"Desarrollar\" en Preferencias primero, luego \"Mostrar consola de JavaScript\"</td></tr>\n</table>\n\n<h2>Pide que explique antes de corregir</h2>\n<p>Como viste en <em>El Gran Repositorio de Prompts</em>, pedirle a la IA que explique la causa antes de corregir te ayuda a entender qué pasó — y la próxima vez, quizás puedas resolverlo tú mismo sin ayuda.</p>\n\n<h2>Si el error persiste después de un intento</h2>\n<p>Dile explícitamente a la IA: \"eso no resolvió el problema, sigue pasando lo mismo\" — y vuelve a describir el comportamiento actual. No asumas que el segundo intento automáticamente lo arregló sin volver a probar tú mismo.</p>\n\n<div class=\"warn\">\n⚠️ Prueba SIEMPRE tú mismo después de cada corrección. No asumas que \"la IA dijo que ya está arreglado\" significa que de verdad funciona — verifica antes de seguir avanzando.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es la diferencia entre \"mi botón no funciona\" y un buen reporte de error?","options":["No hay ninguna diferencia","Un buen reporte describe exactamente qué esperabas vs. qué pasó, e incluye el mensaje de error completo de la consola del navegador","Un buen reporte siempre debe ser más corto","Solo importa el tamaño del código, no la descripción"],"correctIndex":1},"id":4,"order":4},{"type":"text","title":"Dale vida a tu app: guarda y organiza datos","description":"De localStorage a opciones más robustas, según lo que tu app realmente necesite.","content":"\n<h2>Repaso: qué ya tienes con localStorage</h2>\n<p>Si seguiste la clase 3, tu app ya guarda datos en <code>localStorage</code> — un almacén simple dentro del propio navegador de cada persona. Es perfecto para empezar, pero tiene límites que vale la pena conocer.</p>\n\n<h2>Las limitaciones de localStorage</h2>\n<table>\n<tr><th>Limitación</th><th>Qué significa en la práctica</th></tr>\n<tr><td>Es local a un solo navegador</td><td>Si abres tu app desde otro dispositivo, no ves los mismos datos.</td></tr>\n<tr><td>Se puede perder</td><td>Si alguien borra los datos del navegador, o usa modo incógnito, los datos desaparecen.</td></tr>\n<tr><td>No se comparte entre usuarios</td><td>Si quieres que varias personas usen la misma app con datos compartidos, localStorage no alcanza.</td></tr>\n</table>\n\n<h2>¿Cuándo necesitas algo más robusto?</h2>\n<p>Si tu app es solo para ti, en un dispositivo, localStorage puede ser suficiente para siempre. Si necesitas que tus datos te sigan entre dispositivos, o que varias personas compartan información, necesitas una <strong>base de datos real</strong> con un servidor detrás — un paso más avanzado, pero con opciones gratuitas para empezar.</p>\n\n<h2>Opciones gratuitas para dar el siguiente paso</h2>\n<table>\n<tr><th>Servicio</th><th>Qué ofrece</th></tr>\n<tr><td>Supabase</td><td>Base de datos con un nivel gratuito generoso, pensado para que la conectes fácilmente desde una app web.</td></tr>\n<tr><td>Firebase (Google)</td><td>Alternativa similar, con base de datos y autenticación de usuarios incluida.</td></tr>\n</table>\n<p>Pídele a tu asistente de IA, con tu definición de app de la clase 2 a la mano: \"Quiero conectar mi app a [Supabase/Firebase] para que mis datos se guarden en la nube en vez de solo en localStorage. Guíame paso a paso, empezando por crear la cuenta gratuita.\"</p>\n\n<div class=\"warn\">\n⚠️ En cuanto conectes una base de datos real, aparecen consideraciones de seguridad (¿quién puede leer o modificar qué datos?) que no existían con localStorage. Para una app personal simple, las reglas por defecto de estos servicios suelen bastar — para una app que otros usuarios usarán, pídele a la IA explícitamente que te ayude a configurar permisos de acceso correctos antes de compartirla.\n</div>\n\n<div class=\"tip\">\n💡 Para este curso, localStorage es suficiente — este módulo existe para que sepas que existe un siguiente nivel, cuando (y si) lo necesites.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es una limitación real de guardar datos solo con localStorage?","options":["No tiene ninguna limitación","Es local a un solo navegador — no se comparte entre dispositivos ni entre distintos usuarios","Solo funciona en Google Chrome","Requiere pagar una suscripción mensual"],"correctIndex":1},"id":5,"order":5},{"type":"text","title":"Pruébala de verdad antes de mostrarla a nadie","description":"La diferencia entre \"parece que funciona\" y \"de verdad funciona\".","content":"\n<h2>Por qué \"se ve bien\" no es lo mismo que \"funciona bien\"</h2>\n<p>Es fácil probar solo el camino feliz: agregas una tarea, se ve bien, das por hecho que todo funciona. Los problemas reales casi siempre aparecen en los <strong>casos límite</strong> — situaciones que no probaste a propósito.</p>\n\n<h2>Una lista de casos límite para probar cualquier app simple</h2>\n<table>\n<tr><th>Caso límite</th><th>Qué revisar</th></tr>\n<tr><td>Campo vacío</td><td>¿Qué pasa si presionas \"Agregar\" sin escribir nada?</td></tr>\n<tr><td>Texto muy largo</td><td>¿Se ve bien una tarea con una oración muy larga?</td></tr>\n<tr><td>Caracteres especiales</td><td>¿Funciona si escribes emojis, comillas, o símbolos raros?</td></tr>\n<tr><td>Muchos elementos</td><td>¿Sigue funcionando bien con 50 tareas en la lista?</td></tr>\n<tr><td>Recargar la página</td><td>¿Los datos siguen ahí después de refrescar?</td></tr>\n<tr><td>Otro navegador o dispositivo</td><td>¿Se ve razonable en tu teléfono, no solo en tu computadora?</td></tr>\n</table>\n\n<h2>Pídele a la IA que piense en casos límite por ti</h2>\n<p>Como viste en <em>El Gran Repositorio de Prompts</em>: <code>\"¿Qué casos límite no estoy considerando en esta app? Dame una lista para probar.\"</code> — un prompt simple que puede revelar problemas que no se te hubieran ocurrido.</p>\n\n<h2>Prueba en un dispositivo distinto al que la construiste</h2>\n<p>Si construiste tu app en una computadora, ábrela también en tu teléfono antes de darla por terminada — muchos problemas de diseño solo se notan en pantallas más pequeñas.</p>\n\n<h2>Pide una segunda opinión humana</h2>\n<div class=\"tip\">\n💡 Antes de publicarla, pídele a alguien más que la use sin darle instrucciones — obsérvalo (o pregúntale después) dónde se confundió. Los problemas que tú ya no ves (porque conoces tu propia app de memoria) suelen ser obvios para alguien que la usa por primera vez.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué es importante probar \"casos límite\" (campo vacío, texto muy largo, muchos elementos) en vez de solo el uso normal?","options":["No es importante, solo hay que probar el uso normal","Porque los problemas reales casi siempre aparecen en situaciones que no probaste a propósito, no en el camino feliz esperado","Porque los casos límite son más fáciles de probar","Porque las apps nunca tienen errores en el uso normal"],"correctIndex":1},"id":6,"order":6},{"type":"text","title":"Publícala gratis: tu app con una dirección real en internet","description":"De un archivo en tu computadora a algo que cualquiera puede visitar.","content":"\n<h2>Opciones gratuitas para publicar</h2>\n<table>\n<tr><th>Servicio</th><th>Ideal para</th></tr>\n<tr><td><strong>GitHub Pages</strong></td><td>Apps simples de HTML/CSS/JavaScript, gratis, directamente desde un repositorio de GitHub — si tomaste <em>Git y GitHub</em>, ya tienes lo necesario para esto.</td></tr>\n<tr><td><strong>Vercel</strong></td><td>Apps más complejas también, con un flujo muy simple de publicar conectando tu repositorio.</td></tr>\n<tr><td><strong>Netlify</strong></td><td>Alternativa similar a Vercel, también con un nivel gratuito generoso.</td></tr>\n</table>\n\n<h2>El camino más simple: GitHub Pages</h2>\n<ol>\n<li>Sube tu archivo <code>mi-app.html</code> (renómbralo a <code>index.html</code>) a un repositorio nuevo en GitHub.</li>\n<li>En la configuración del repositorio, busca la sección \"Pages\".</li>\n<li>Activa GitHub Pages, eligiendo la rama principal como fuente.</li>\n<li>En unos minutos, tu app tendrá una dirección pública, algo como <code>tu-usuario.github.io/tu-repositorio</code>.</li>\n</ol>\n\n<div class=\"tip\">\n💡 Si no recuerdas cómo subir archivos a un repositorio de GitHub, el curso <em>Git y GitHub: de Cero a Experto</em> de esta escuela tiene una consola interactiva dedicada exactamente a eso.\n</div>\n\n<h2>Comparte tu app y pide retroalimentación</h2>\n<p>Una vez publicada, compártela con alguien y observa cómo la usa sin darle instrucciones — es la prueba final, más allá de lo que ya probaste tú mismo en la clase anterior.</p>\n\n<h2>Un recordatorio importante sobre datos</h2>\n<div class=\"warn\">\n⚠️ Si tu app usa localStorage (clase 6), recuerda que los datos son <strong>locales al navegador de cada persona</strong> que la visite — cada quien tendrá su propia lista de tareas separada, no una compartida. Eso está perfecto para una app personal; si quisieras datos compartidos entre usuarios, necesitarías la base de datos real que viste como siguiente paso.\n</div>\n\n<h2>Ya lo lograste</h2>\n<p>Si llegaste hasta aquí con una app funcionando y publicada: felicidades, de verdad — construiste algo real de principio a fin, usando exactamente el proceso que usan los desarrolladores profesionales cuando trabajan con IA: definir, construir, depurar, probar, publicar.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué necesitas tener en cuenta si tu app usa localStorage y la compartes públicamente con otras personas?","options":["Nada especial, todos verán los mismos datos","Los datos son locales al navegador de cada persona — cada quien tendrá su propia información separada, no compartida","localStorage no funciona en apps publicadas","Es obligatorio usar una base de datos real antes de publicar cualquier app"],"correctIndex":1},"id":7,"order":7},{"type":"text","title":"Qué sigue: mantenimiento, límites del vibe coding, y tu próximo proyecto","description":"Cierre honesto sobre cuándo este enfoque basta, y cuándo necesitas más.","content":"\n<h2>Mantener tu app viva</h2>\n<p>Publicar no es el final — si encuentras un error después, o quieres agregar una función nueva, el proceso es el mismo que ya conoces: descríbelo a la IA, prueba el cambio, y vuelve a publicar. Guarda el enlace a tu conversación original (o a tu Proyecto, si usas Claude — ver <em>Domina Claude</em>) para no perder el contexto acumulado.</p>\n\n<h2>Los límites honestos del vibe coding</h2>\n<table>\n<tr><th>Funciona muy bien para...</th><th>Necesita más cuidado (o un desarrollador con experiencia) para...</th></tr>\n<tr><td>Proyectos personales y prototipos</td><td>Software que maneja datos sensibles de otras personas (salud, finanzas, identidad)</td></tr>\n<tr><td>Herramientas internas simples</td><td>Apps con muchos usuarios simultáneos y necesidades de rendimiento serias</td></tr>\n<tr><td>Aprender y experimentar</td><td>Sistemas donde un error de seguridad tendría consecuencias reales importantes</td></tr>\n<tr><td>Validar una idea rápido, antes de invertir más</td><td>Software que necesita mantenerse y escalar por años, con un equipo</td></tr>\n</table>\n\n<div class=\"warn\">\n⚠️ Como viste en <em>Actualidad de la IA</em>: el vibe coding es excelente para prototipos y aprendizaje. Para cualquier proyecto real con datos de usuarios reales o dinero de por medio, la revisión de alguien con experiencia técnica sigue siendo indispensable — no opcional.\n</div>\n\n<h2>Tu próximo proyecto</h2>\n<p>Ahora que ya recorriste el proceso completo una vez, elige tu segunda app — algo un poco más ambicioso que la primera. Aplica exactamente el mismo método: define, elige stack, construye, depura, prueba, publica.</p>\n\n<h2>Sigue aprendiendo en esta escuela</h2>\n<table>\n<tr><th>Si quieres...</th><th>Ve a...</th></tr>\n<tr><td>Entender mejor el control de versiones para proyectos más grandes</td><td>Git y GitHub: de Cero a Experto</td></tr>\n<tr><td>Profundizar en programación \"de verdad\"</td><td>Los cursos de la Escuela de Programación de esta plataforma</td></tr>\n<tr><td>Automatizar tareas combinando Python e IA</td><td>Automatización con Python e IA (esta misma academia)</td></tr>\n<tr><td>Entender cómo piensan los modelos que usaste</td><td>Aprendizaje Automático: Cómo Piensa una Máquina</td></tr>\n</table>\n\n<div class=\"tip\">\n💡 El curso terminó, pero el hábito que construiste — definir antes de construir, iterar en vez de empezar de cero, probar casos límite, verificar antes de confiar — te va a servir en cualquier proyecto futuro, con o sin IA de por medio.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"Según el cierre del curso, ¿para qué tipo de proyecto sigue siendo indispensable la revisión de alguien con experiencia técnica?","options":["Para cualquier prototipo personal simple","Para proyectos reales con datos sensibles de usuarios, dinero de por medio, o consecuencias serias si algo sale mal","El vibe coding nunca necesita revisión adicional","Solo para apps que nunca se van a publicar"],"correctIndex":1},"id":8,"order":8}]',
  '{}'::jsonb
)
on conflict (id) do update set
  title = excluded.title, description = excluded.description, ai_instructions = excluded.ai_instructions,
  icon = excluded.icon, color = excluded.color, category = excluded.category,
  subcategory = excluded.subcategory, difficulty = excluded.difficulty, locked = excluded.locked,
  modules = excluded.modules, translations = excluded.translations, updated_at = now();

insert into public.courses
  (id, title, description, ai_instructions, icon, color, category, subcategory, difficulty, locked, modules, translations)
values (
  'course-automatizacion-python-ia', 'Automatización con Python e IA', 'Haz que tu computadora trabaje sola: scripts de Python que organizan archivos, leen correos, llaman a una IA para resumir o clasificar, y corren solos en un horario — sin que tengas que acordarte de hacerlo tú. De cero a tu primera automatización real, con manejo de errores incluido.', 'Eres el Mago, profesor de la Escuela de Programación de Oliver Academy, guiando el curso "Automatización con Python e IA". Explica código Python con paciencia, asumiendo que el alumno puede no tener experiencia previa de programación. Sé muy insistente en las buenas prácticas de seguridad al manejar llaves de API (nunca en el código, siempre en variables de entorno) y en el manejo de errores — una automatización que falla en silencio es peor que una que no existe. Da siempre el porqué antes que el cómo.',
  '🐍', '#eab308', 'Programación', 'APIs y Automatización', 'intermedio', false,
  '[{"type":"text","title":"Bienvenida: haz que tu computadora trabaje mientras tú no","description":"La diferencia entre programar y automatizar, y qué vas a construir.","content":"\n<h2>Programar vs. automatizar</h2>\n<p><strong>Programar</strong> es escribir instrucciones para que una computadora haga algo cuando tú se lo pides. <strong>Automatizar</strong> es un paso más allá: escribir instrucciones que la computadora ejecuta <strong>por sí sola</strong>, en un horario o cuando ocurre algo específico, sin que tú tengas que estar ahí para iniciarlas cada vez.</p>\n\n<h2>Por qué Python + IA es una combinación tan poderosa</h2>\n<p>Python es, desde hace años, el lenguaje más usado para scripts y automatización — simple de leer, con librerías para casi cualquier tarea. Combinado con una IA (llamada desde tu código, no solo desde un chat), puedes automatizar tareas que antes requerían <strong>juicio humano</strong>: resumir un texto, clasificar un correo, decidir si una foto necesita revisión — no solo tareas mecánicas repetitivas.</p>\n\n<h2>El mapa del curso</h2>\n<table>\n<tr><th>Parte</th><th>Qué vas a construir</th></tr>\n<tr><td>1. Fundamentos rápidos</td><td>Lo mínimo de Python que necesitas si nunca programaste.</td></tr>\n<tr><td>2. Llama a una IA desde tu código</td><td>No desde un chat — desde un script que tú controlas.</td></tr>\n<tr><td>3. Automatiza archivos</td><td>Que Python organice, lea y escriba archivos por ti.</td></tr>\n<tr><td>4. Ponlo en horario</td><td>Que corra solo, sin que tengas que acordarte.</td></tr>\n<tr><td>5. Un proyecto completo</td><td>Un resumidor automático de archivos de principio a fin.</td></tr>\n<tr><td>6. Manejo de errores</td><td>Para que tu automatización no falle en silencio.</td></tr>\n</table>\n\n<div class=\"tip\">\n💡 Si ya tomaste <em>APIs con Python: Crea tu Bot Consultor de Telegram</em> de esta escuela, ya tienes buena base de Python y de llamar APIs — este curso amplía esa base hacia la automatización general (archivos, horarios) en vez de un solo bot específico.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es la diferencia entre \"programar\" y \"automatizar\"?","options":["Son exactamente lo mismo","Programar es escribir instrucciones que ejecutas cuando quieres; automatizar es que esas instrucciones corran solas, en un horario o evento, sin que tú las inicies cada vez","Automatizar no requiere ningún código","Programar solo aplica a páginas web"],"correctIndex":1},"id":0,"order":0},{"type":"text","title":"Fundamentos rápidos de Python (si nunca programaste)","description":"Lo mínimo indispensable para seguir el resto del curso, en una sola clase.","content":"\n<h2>Instala Python</h2>\n<p>Descarga Python desde <code>python.org</code> (o instálalo con <code>pkg install python</code> si ya tomaste el curso de <em>Termux</em>). Confirma la instalación:</p>\n<pre><code>python --version</code></pre>\n\n<h2>Variables: guardar información con un nombre</h2>\n<pre><code>nombre = \"Ada\"\nedad = 16\nprint(f\"Hola {nombre}, tienes {edad} años\")</code></pre>\n<p>Una <strong>variable</strong> guarda un valor bajo un nombre que puedes reutilizar. El texto con <code>f</code> antes de las comillas (<em>f-string</em>) te deja insertar variables directamente dentro de un texto.</p>\n\n<h2>Listas: varios valores juntos</h2>\n<pre><code>tareas = [\"Estudiar\", \"Hacer ejercicio\", \"Leer\"]\nfor tarea in tareas:\n    print(f\"Pendiente: {tarea}\")</code></pre>\n<p>Una <strong>lista</strong> guarda varios valores en orden. El <code>for</code> recorre cada elemento, uno por uno — la base de casi toda automatización que procesa \"muchas cosas\".</p>\n\n<h2>Funciones: código que reutilizas</h2>\n<pre><code>def saludar(nombre):\n    return f\"Hola, {nombre}\"\n\nprint(saludar(\"Ada\"))</code></pre>\n<p>Una <strong>función</strong> empaqueta código para reutilizarlo con distintos valores, sin copiar y pegar el mismo bloque una y otra vez.</p>\n\n<h2>Instalar librerías con pip</h2>\n<pre><code>pip install requests</code></pre>\n<p><code>pip</code> es el instalador de paquetes de Python — instala código que otras personas ya escribieron, para no reinventar todo desde cero. Lo vas a usar en la siguiente clase para llamar a una IA desde tu código.</p>\n\n<div class=\"tip\">\n💡 Con estas cuatro piezas (variables, listas, funciones, pip) ya tienes suficiente Python para seguir el resto del curso. Si quieres profundizar más en el lenguaje en sí, el curso <em>APIs con Python</em> de esta escuela tiene más fundamentos, y la Academia de Linux tiene consolas interactivas de Python para practicar.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Para qué sirve \"pip\" en Python?","options":["Para ejecutar programas más rápido","Es el instalador de paquetes de Python: instala código que otras personas ya escribieron, sin tener que reinventarlo tú mismo","Es un editor de texto","Solo sirve para instalar Python mismo"],"correctIndex":1},"id":1,"order":1},{"type":"text","title":"Llama a una IA desde tu código, no desde un chat","description":"La diferencia entre conversar con una IA y programar con ella.","content":"\n<h2>Del chat a la API</h2>\n<p>Cuando conversas con Claude, GPT o Gemini en su app, estás usando una interfaz pensada para humanos. Cuando quieres que <strong>tu propio código</strong> le pida algo a una IA (sin que tú lo escribas a mano cada vez), usas su <strong>API</strong> — la misma idea que viste en <em>APIs con Python: Crea tu Bot Consultor de Telegram</em>, aplicada aquí a un proveedor de IA en vez de a NASA o Pokémon.</p>\n\n<h2>Guarda tu llave de forma segura — nunca en el código</h2>\n<div class=\"warn\">\n⚠️ Como viste en <em>Domina Claude</em>: tu llave de API es una credencial real, como una contraseña. <strong>Nunca</strong> la escribas directamente en tu código — si subes ese archivo a un repositorio público, cualquiera podría usar tu llave y generarte cargos. Guárdala en una <strong>variable de entorno</strong> en su lugar.\n</div>\n<pre><code># En una terminal (no en tu código):\nexport ANTHROPIC_API_KEY=\"tu-llave-aqui\"</code></pre>\n<p>O mejor aún, en un archivo <code>.env</code> que <strong>nunca</strong> subes a Git (agrégalo a tu <code>.gitignore</code> — repasa el curso de Git y GitHub si no recuerdas cómo).</p>\n\n<h2>Un ejemplo mínimo de llamada</h2>\n<pre><code>import os\nimport anthropic\n\ncliente = anthropic.Anthropic(api_key=os.environ[\"ANTHROPIC_API_KEY\"])\n\nrespuesta = cliente.messages.create(\n    model=\"claude-sonnet-5\",\n    max_tokens=200,\n    messages=[{\"role\": \"user\", \"content\": \"Resume esto en una línea: \" + texto_largo}]\n)\n\nprint(respuesta.content[0].text)</code></pre>\n\n<h2>Qué está pasando en este código</h2>\n<table>\n<tr><th>Línea</th><th>Qué hace</th></tr>\n<tr><td><code>os.environ[\"ANTHROPIC_API_KEY\"]</code></td><td>Lee la llave desde la variable de entorno, nunca escrita directamente en el código.</td></tr>\n<tr><td><code>cliente.messages.create(...)</code></td><td>Envía tu mensaje a la IA y espera la respuesta.</td></tr>\n<tr><td><code>respuesta.content[0].text</code></td><td>Extrae el texto de la respuesta, para poder usarlo en el resto de tu programa.</td></tr>\n</table>\n\n<div class=\"tip\">\n💡 Este mismo patrón (llamar a una API de IA desde código, procesar la respuesta, usarla en algo más grande) es exactamente cómo Oliver Academy conecta con tu propia mascota de IA — no es teoría, es el mecanismo real detrás de una función que ya usaste como estudiante.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Dónde NUNCA debe escribirse una llave de API?","options":["En una variable de entorno","Directamente en el código, especialmente si ese código se sube a un repositorio público","En un archivo .env agregado al .gitignore","En la terminal al configurar el entorno"],"correctIndex":1},"id":2,"order":2},{"type":"text","title":"Automatiza archivos: que Python organice y procese por ti","description":"Leer, escribir y mover archivos — la base de casi cualquier automatización.","content":"\n<h2>Leer un archivo de texto</h2>\n<pre><code>with open(\"notas.txt\", \"r\", encoding=\"utf-8\") as archivo:\n    contenido = archivo.read()\nprint(contenido)</code></pre>\n<p>El <code>with</code> asegura que el archivo se cierre automáticamente al terminar, incluso si ocurre un error — una buena práctica que evita archivos \"atascados\" abiertos.</p>\n\n<h2>Escribir un archivo nuevo</h2>\n<pre><code>with open(\"resumen.txt\", \"w\", encoding=\"utf-8\") as archivo:\n    archivo.write(\"Este es el resumen generado por la IA.\")</code></pre>\n\n<h2>Recorrer todos los archivos de una carpeta</h2>\n<pre><code>import os\n\nfor nombre_archivo in os.listdir(\"documentos\"):\n    if nombre_archivo.endswith(\".txt\"):\n        print(f\"Encontrado: {nombre_archivo}\")</code></pre>\n<p>Este patrón — recorrer una carpeta, filtrar por tipo de archivo, y hacer algo con cada uno — es la base de la mayoría de las automatizaciones de archivos: renombrar en lote, convertir formatos, o (como verás en el proyecto de este curso) resumir cada archivo con IA.</p>\n\n<h2>Mover y organizar archivos automáticamente</h2>\n<pre><code>import shutil\n\nshutil.move(\"documentos/reporte.txt\", \"archivados/reporte.txt\")</code></pre>\n<p>La librería <code>shutil</code> (incluida en Python, sin instalar nada extra) te deja mover, copiar y organizar archivos por código — la base de un \"organizador automático de carpetas\".</p>\n\n<h2>Combinando todo: un mini ejemplo</h2>\n<div class=\"example\">\n<strong>Idea de automatización simple:</strong> un script que recorre tu carpeta de Descargas, y mueve cada archivo <code>.pdf</code> a una carpeta llamada \"Documentos\", y cada imagen a una carpeta llamada \"Fotos\" — usando exactamente los tres patrones que acabas de ver: recorrer, filtrar por tipo, y mover.\n</div>\n\n<div class=\"tip\">\n💡 Prueba siempre tus scripts de archivos primero sobre una carpeta de prueba con copias, nunca sobre tus archivos originales importantes — un error en el código podría mover o sobrescribir algo que no querías tocar.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué hace la librería \"shutil\" en Python?","options":["Instala nuevas versiones de Python","Permite mover, copiar y organizar archivos por código","Se conecta a APIs de IA","Solo sirve para leer archivos, no para moverlos"],"correctIndex":1},"id":3,"order":3},{"type":"text","title":"Ponlo en horario: que corra solo, sin que tengas que acordarte","description":"De ejecutar un script a mano a que se ejecute automáticamente.","content":"\n<h2>El problema: acordarte de correrlo tú mismo</h2>\n<p>Un script que solo corre cuando tú lo ejecutas manualmente no es realmente una automatización todavía — sigue dependiendo de tu memoria. El siguiente paso es que corra <strong>solo</strong>, en un horario.</p>\n\n<h2>Opción 1: la librería schedule (simple, dentro de Python)</h2>\n<pre><code>import schedule\nimport time\n\ndef tarea_diaria():\n    print(\"Ejecutando mi automatización...\")\n\nschedule.every().day.at(\"09:00\").do(tarea_diaria)\n\nwhile True:\n    schedule.run_pending()\n    time.sleep(60)</code></pre>\n<p>Este script se queda corriendo, revisando cada minuto si es hora de ejecutar la tarea programada. Es simple de entender, pero requiere que la computadora (o un servidor) esté encendida y el script corriendo todo el tiempo.</p>\n\n<h2>Opción 2: el planificador del sistema operativo</h2>\n<table>\n<tr><th>Sistema</th><th>Herramienta</th></tr>\n<tr><td>Linux / macOS</td><td><code>cron</code> — programa tareas para que el propio sistema operativo las ejecute, incluso si tu script no está corriendo activamente.</td></tr>\n<tr><td>Windows</td><td>Programador de tareas (Task Scheduler)</td></tr>\n</table>\n<p>Con <code>cron</code>, por ejemplo, agregarías una línea como esta (editando con <code>crontab -e</code>):</p>\n<pre><code>0 9 * * * python /ruta/a/tu_script.py</code></pre>\n<p>Esto ejecuta tu script todos los días a las 9:00 AM, sin que necesites dejar nada corriendo manualmente de fondo.</p>\n\n<h2>¿Cuál elegir?</h2>\n<table>\n<tr><th>Opción</th><th>Ventaja</th><th>Cuándo usarla</th></tr>\n<tr><td><code>schedule</code> (dentro de Python)</td><td>Simple, todo en un solo archivo</td><td>Scripts pequeños que ya planeas dejar corriendo de fondo.</td></tr>\n<tr><td><code>cron</code> / Task Scheduler</td><td>Más confiable, integrado al sistema operativo</td><td>Automatizaciones serias que necesitas que corran sí o sí.</td></tr>\n</table>\n\n<div class=\"tip\">\n💡 Si tomaste el curso de <em>Termux</em> de la Academia de Linux, ya viste <code>cron</code> (con el paquete <code>cronie</code>) — puedes usar exactamente ese conocimiento para programar tus automatizaciones de Python incluso desde tu teléfono.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Cuál es la ventaja de usar \"cron\" (o el Programador de tareas de Windows) sobre la librería schedule de Python?","options":["No tiene ninguna ventaja real","cron ejecuta tu script según el horario definido incluso si tu script no está corriendo activamente de fondo, integrado directamente al sistema operativo","schedule es más confiable que cron","cron solo funciona en Windows"],"correctIndex":1},"id":4,"order":4},{"type":"text","title":"Proyecto: un resumidor automático de archivos","description":"Combina todo lo que aprendiste en un proyecto completo, de principio a fin.","content":"\n<h2>Lo que vas a construir</h2>\n<p>Un script que, cada día a una hora fija: revisa una carpeta en busca de archivos de texto nuevos, le pide a una IA un resumen de cada uno, y guarda esos resúmenes en una carpeta separada — combinando exactamente lo que viste en las clases 3, 4 y 5.</p>\n\n<h2>El esqueleto completo</h2>\n<pre><code>import os\nimport anthropic\n\ncliente = anthropic.Anthropic(api_key=os.environ[\"ANTHROPIC_API_KEY\"])\n\ndef resumir_texto(texto):\n    respuesta = cliente.messages.create(\n        model=\"claude-sonnet-5\",\n        max_tokens=150,\n        messages=[{\"role\": \"user\", \"content\": f\"Resume esto en 3 líneas:\\n\\n{texto}\"}]\n    )\n    return respuesta.content[0].text\n\ndef procesar_carpeta():\n    for nombre in os.listdir(\"documentos\"):\n        if not nombre.endswith(\".txt\"):\n            continue\n        ruta_original = os.path.join(\"documentos\", nombre)\n        with open(ruta_original, \"r\", encoding=\"utf-8\") as f:\n            texto = f.read()\n\n        resumen = resumir_texto(texto)\n\n        ruta_resumen = os.path.join(\"resumenes\", f\"resumen_{nombre}\")\n        with open(ruta_resumen, \"w\", encoding=\"utf-8\") as f:\n            f.write(resumen)\n        print(f\"Resumido: {nombre}\")\n\nprocesar_carpeta()</code></pre>\n\n<h2>Cómo se conecta cada pieza</h2>\n<table>\n<tr><th>Parte del código</th><th>De qué clase viene</th></tr>\n<tr><td><code>cliente.messages.create(...)</code></td><td>Clase 3 — llamar a una IA desde código.</td></tr>\n<tr><td><code>os.listdir(...)</code>, <code>open(...)</code></td><td>Clase 4 — recorrer y leer archivos.</td></tr>\n<tr><td>Falta agregar <code>schedule</code> o <code>cron</code></td><td>Clase 5 — para que corra sola cada día.</td></tr>\n</table>\n\n<h2>Tu turno: personalízalo</h2>\n<ul>\n<li>Cambia el prompt para pedir algo distinto a un resumen (por ejemplo, extraer solo las fechas mencionadas).</li>\n<li>Agrega un filtro para solo procesar archivos que no se hayan resumido antes.</li>\n<li>Combínalo con la clase 5 para que corra automáticamente cada mañana.</li>\n</ul>\n\n<div class=\"tip\">\n💡 Usa a tu propio asistente de IA para adaptar este esqueleto a tu caso: pégale el código y dile exactamente qué quieres cambiar, como practicaste en <em>Crea tu Primera App con IA</em>.\n</div>\n","exercises":[],"resources":[],"quiz":{"question":"¿Qué tres piezas de las clases anteriores se combinan en el proyecto de esta clase?","options":["Solo el manejo de errores","Llamar a una IA desde código, leer/recorrer archivos, y (para completarlo del todo) programarlo en un horario","Solo la instalación de Python","Ninguna, es contenido completamente nuevo"],"correctIndex":1},"id":5,"order":5},{"type":"text","title":"Manejo de errores: que tu automatización no falle en silencio","description":"La diferencia entre una automatización confiable y una que te falla sin avisarte.","content":"\n<h2>El peor tipo de fallo: el silencioso</h2>\n<p>Un script que se detiene con un error visible es molesto, pero al menos lo notas. El peligro real es una automatización que falla <strong>en silencio</strong> — deja de funcionar y tú no te enteras hasta días después, cuando notas que faltan resúmenes, o que tu carpeta de organización no se movió como esperabas.</p>\n\n<h2>try/except: atrapa errores sin que todo se detenga</h2>\n<pre><code>try:\n    resumen = resumir_texto(texto)\nexcept Exception as error:\n    print(f\"Error al resumir {nombre}: {error}\")\n    continue  # sigue con el siguiente archivo, en vez de detener todo el script</code></pre>\n<p>El bloque <code>try</code> intenta ejecutar el código; si algo falla, el bloque <code>except</code> lo atrapa en vez de que el programa entero se detenga — útil especialmente cuando procesas muchos archivos y uno solo con un problema no debería arruinar el resto.</p>\n\n<h2>No te quedes solo con \"algo falló\" — registra qué y cuándo</h2>\n<pre><code>import logging\n\nlogging.basicConfig(filename=\"automatizacion.log\", level=logging.INFO)\n\nlogging.info(f\"Procesando {nombre}\")\nlogging.error(f\"Fallo al procesar {nombre}: {error}\")</code></pre>\n<p>Un archivo de <strong>log</strong> (registro) guarda un historial de qué pasó y cuándo — así, si algo falla, puedes revisar el log en vez de intentar recordar o adivinar qué salió mal.</p>\n\n<h2>Notifícate a ti mismo cuando algo falla</h2>\n<p>Para automatizaciones importantes, no basta con guardar el error en un log que quizás nunca revises — considera enviarte una notificación real (un mensaje de Telegram, como viste en <em>APIs con Python: Crea tu Bot Consultor de Telegram</em>, o un correo) cuando algo falla, para enterarte de inmediato en vez de días después.</p>\n\n<h2>Checklist de una automatización confiable</h2>\n<table>\n<tr><th>Pregunta</th><th>Por qué importa</th></tr>\n<tr><td>¿Qué pasa si un archivo está vacío o corrupto?</td><td>No debería tumbar todo el script.</td></tr>\n<tr><td>¿Qué pasa si la API de IA no responde (sin internet, límite alcanzado)?</td><td>Debe registrarse el error, no fallar en silencio.</td></tr>\n<tr><td>¿Cómo me entero si algo salió mal?</td><td>Un log como mínimo; una notificación activa, idealmente.</td></tr>\n<tr><td>¿Puedo volver a correrlo sin duplicar trabajo ya hecho?</td><td>Evita reprocesar archivos ya resumidos innecesariamente.</td></tr>\n</table>\n\n<div class=\"warn\">\n⚠️ Cuanto más \"invisible\" es una automatización (corre sola, sin que la veas), más importante es que tenga buen manejo de errores — nadie está mirando en tiempo real para notar si algo salió mal.\n</div>\n\n<h2>Cierre del curso</h2>\n<p>Ya sabes llamar a una IA desde tu propio código, automatizar archivos, programar tareas en horario, y hacerlo con manejo de errores confiable. Con estas piezas, puedes automatizar prácticamente cualquier tarea repetitiva de tu día a día que combine archivos, decisiones simples, y ayuda de una IA.</p>\n","exercises":[],"resources":[],"quiz":{"question":"¿Por qué es peligroso que una automatización falle \"en silencio\"?","options":["No es peligroso, es lo ideal","Porque dejas de notar que algo dejó de funcionar hasta días después, cuando ya causó un problema mayor","Porque hace que el código sea más lento","Porque consume más memoria que un error visible"],"correctIndex":1},"id":6,"order":6}]',
  '{}'::jsonb
)
